window.TXB=window.TXB||{};TXB["alab/Job"]={"1:1":"عاش في أرض عوص رجل اسمه أيوب، كان صالحا كاملا يتقي الله ويحيد عن الشر.","1:2":"وأنجب أيوب سبعة أبناء وثلاث بنات.","1:3":"وبلغت مواشيه سبعة آلاف من الغنم، وثلاثة آلاف جمل، وخمس مئة زوج من البقر، وخمس مئة أتان. أما خدمه فكانوا كثيرين جدا. وكان هذا الرجل أعظم أبناء المشرق قاطبة.","1:4":"واعتاد أولاده أن يقيموا المآدب في بيت كل منهم بدوره، ويدعون أخواتهم الثلاث إليها ليشاركن فيها.","1:5":"وحالما تنقضي أيام الولائم كان أيوب يستدعي أبناءه ويقدسهم، فكان ينهض مبكرا في الصباح ويقرب محرقات على عددهم قائلا: «لئلا يكون بني قد أخطأوا في قلوبهم وجدفوا على الله». هذا ما واظب عليه أيوب دائما.","1:6":"وحدث ذات يوم أن مثل بنو الله أمام الرب، فاندس الشيطان في وسطهم.","1:7":"فسأل الرب الشيطان: «من أين جئت؟» فأجاب الشيطان: «من الطواف في الأرض والتجول فيها».","1:8":"فقال الرب للشيطان: «هل راقبت عبدي أيوب، فإنه لا نظير له في الأرض، فهو رجل كامل صالح يتقي الله ويحيد عن الشر».","1:9":"فأجاب الشيطان: «أمجانا يتقي أيوب الله ؟","1:10":"ألم تسيج حوله وحول بيته وحول كل ما يملك. لقد باركت كل ما يقوم به من أعمال، فملأت مواشيه الأرض.","1:11":"ولكن حالما تمد يدك وتمس جميع ما يملك، فإنه في وجهك يجدف عليك».","1:12":"فقال الرب للشيطان: «ها أنا أسلمك كل ما يملك. إنما لا تمد يدك إليه لتؤذيه». ثم انصرف الشيطان من حضرة الرب.","1:13":"وذات يوم، فيما كان أبناء أيوب وبناته يأكلون ويشربون خمرا في بيت أخيهم الأكبر،","1:14":"أقبل رسول إلى أيوب وقال: «بينما كانت البقر تحرث والأتن ترعى إلى جوارها،","1:15":"هاجمنا غزاة السبئيين وأخذوها، وقتلوا الغلمان بحد السيف، وأفلت أنا وحدي لأخبرك».","1:16":"وفيما هو يتكلم أقبل آخر قائلا: «لقد نزلت صاعقة من السماء أحرقت الغنم والغلمان والتهمتهم، وأفلت أنا وحدي لأخبرك».","1:17":"وبينما هذا يتكلم أقبل ثالث وقال: «لقد غزتنا ثلاث فرق من الكلدانيين، واستولوا على الجمال، وقتلوا الغلمان بحد السيف، وأفلت أنا وحدي لأخبرك».","1:18":"وإذ كان هذا لا يزال يتكلم جاء رجل رابع وقال: «بينما كان أبناؤك وبناتك يأكلون ويشربون خمرا في بيت أخيهم الأكبر،","1:19":"هبت ريح شديدة من عبر الصحراء، فاجتاحت أركان البيت الأربعة، فانهار على الغلمان وماتوا جميعا، وأفلت أنا وحدي لأخبرك».","1:20":"فقام أيوب ومزق جبته وجز شعر رأسه وأكب على الأرض ساجدا،","1:21":"وقال: «عريانا خرجت من بطن أمي وعريانا أعود إلى هناك. الرب أعطى والرب أخذ، فليكن اسم الرب مباركا».","1:22":"في هذا كله لم يخطىء أيوب في حق الله ولم يعز له حماقة.","2:1":"ثم مثل بنو الله مرة أخرى في حضرة الرب، واندس الشيطان أيضا في وسطهم،","2:2":"فسأل الرب الشيطان: «من أين جئت؟» فأجاب الشيطان: «من الطواف في الأرض والتجول فيها».","2:3":"فقال الرب للشيطان: «هل راقبت عبدي أيوب فإنه لا نظير له في الأرض، فهو رجل كامل صالح، يتقي الله ويحيد عن الشر، وحتى الآن لا يزال معتصما بكماله، مع أنك أثرتني عليه لأهلكه من غير داع».","2:4":"فأجاب الشيطان: «جلد بجلد، فالإنسان يبذل كل ما يملك فداء نفسه.","2:5":"ولكن حالما تمد يدك إليه وتمس عظمه ولحمه فإنه في وجهك يجدف عليك».","2:6":"فقال الرب للشيطان: «ها أنا أسلمه إليك، ولكن احفظ نفسه».","2:7":"فانصرف الشيطان من حضرة الرب، وابتلى أيوب بقروح انتشرت في بدنه كله، من قمة الرأس إلى أخمص القدم،","2:8":"فجلس أيوب وسط الرماد وتناول شقفة يحك بها قروحه.","2:9":"فقالت له زوجته: «أما زلت معتصما بكمالك؟ جدف على الله ومت».","2:10":"فأجابها: «أنت تتكلمين كالجاهلات! أنقبل الخير من عند الله والشر لا نقبل؟». في هذا كله لم ترتكب شفتا أيوب خطأ في حق الله.","2:11":"وعندما سمع أصحاب أيوب الثلاثة بما حاق به من شر، توافدوا إليه من مقر إقامتهم، وهم أليفاز التيماني، وبلدد الشوحي، وصوفر النعماتي، بعد أن تواعدوا على الاجتماع عنده للرثاء له ولتعزيته.","2:12":"وإذ رأوه من بعيد لم يعرفوه لفرط ما حل به، فرفعوا أصواتهم بالبكاء، ومزق كل واحد جبته وذروا ترابا فوق رؤوسهم نحو السماء،","2:13":"ومكثوا جالسين معه على الأرض سبعة أيام وسبع ليال، لم يكلمه فيها أحد منهم بكلمة لشدة ما كان عليه من كآبة.","3:1":"ثم تكلم أيوب، فشتم اليوم الذي ولد فيه،","3:2":"وقال:","3:3":"«ليته باد اليوم الذي ولدت فيه، وفني الليل الذي قيل فيه: قد حبل بطفل ذكر.","3:4":"ليتحول ذلك اليوم إلى ظلام. لا يرعاه الله من فوق، ولا يشرق عليه نهار.","3:5":"ليستول عليه الظلام وظل الموت. ليكتنفه سحاب ولتروعه ظلمات النهار.","3:6":"أما ذلك الليل فليعتقله الدجى المتكاثف، ولا يبتهج مع سائر أيام السنة، ولا يحص في عدد الشهور.","3:7":"ليكن ذلك الليل عاقرا، لا يتردد فيه هتاف.","3:8":"ليلعنه السحرة الحاذقون في إيقاظ التنين!","3:9":"لتظلم كواكب شفقه، وليرتقب النور من غير طائل، ولا ير هدب الفجر،","3:10":"لأنه لم يغلق رحم أمي ولم يستر الشقاء عن عيني.","3:11":"لم لم أمت في الرحم، ولم لم أسلم الروح عندما خرجت من بطن أمي؟","3:12":"لماذا وجدت الركب لتعينني والثدي لترضعني؟","3:13":"وإلا لكنت مازلت مضطجعا ساكنا، ولكنت نائما مستريحا","3:14":"مع ملوك الأرض ومشيريها، الذين بنوا أهراما لأنفسهم.","3:15":"أو مع الرؤساء الذين كنزوا ذهبا وملأوا بيوتهم فضة.","3:16":"أو لماذا لم أطمر في الأرض كسقط لم ير النور؟","3:17":"فهناك يكف الأشرار عن إثارة المتاعب، وهناك يرتاح المرهقون.","3:18":"هناك يطمئن الأسرى جميعا، إذ لا يلاحقهم صوت المسخر.","3:19":"هناك يكون الصغير كالكبير، والعبد متحررا من سيده.","3:20":"لم يوهب الشقي نورا، وذوو النفوس المرة حياة؟","3:21":"الذين يتوقون إلى الموت فلا يقبل، وينقبون عنه أكثر مما ينقبون عن الكنوز الخفية،","3:22":"الذين ينتشون غبطة، ويستبشرون حين يعثرون على ضريح!","3:23":"بل لماذا يوهب نور وحياة لرجل ضلت به طريقه، وسد الله حوله؟","3:24":"استبدلت طعامي بالأنين، وزفرتي تنسكب كالمياه،","3:25":"لأنه قد غشيني ما كنت أخشاه، وداهمني ما كنت أرتعب منه.","3:26":"فلا طمأنينة لي ولا قرار ولا راحة، بعد أن اجتاحتني الكروب».","4:1":"فأجاب أليفاز التيماني:","4:2":"«إن جازف أحد ووجه إليك كلمة فهل يشق ذلك عليك؟ ولكن من يستطيع الامتناع عن الكلام؟","4:3":"لكم أرشدت كثيرين وشددت أيادي مرتخية.","4:4":"ولكم أنهض كلامك العاثر، وثبت الركب المصطكة!","4:5":"والآن إذ داهمك الكرب اعتراك السأم، وإذ مسك ساورك الرعب.","4:6":"أليست تقواك هي معتمدك، وكمال طرقك هو رجاؤك؟","4:7":"اذكر. هل هلك أحد وهو بريء، أو أين أبيد الصالحون؟","4:8":"بل كما شاهدت فإن الحارثين إثما، والزارعين شقاوة، هم يحصدونهما،","4:9":"وبنسمة الله يفنون وبعاصفة غضبه يهلكون.","4:10":"قد يزأر الأسد ويزمجر الليث، ولكن أنياب الأشبال تهشمت.","4:11":"يهلك الليث لتعذر وجود الفريسة، وتتشتت أشبال اللبؤة.","4:12":"ذات مرة أسر إلي بكلمة، فتلقفت أذني منها همسا","4:13":"ففي غمرة الهواجس، في رؤى الليل، عندما طغى السبات على الناس،","4:14":"انتابني رعب ورعدة أرجفا عظامي،","4:15":"وخطرت روح أمام وجهي، فاقشعر شعر جسدي.","4:16":"ثم وقفت، غير أني لم أتبين ملامحها. تماثل لي شكل ما، فران صمت ثم سمعت صوتا منخفضا يقول:","4:17":"أيمكن أن يكون الإنسان أبر من الله، أم الرجل أطهر من خالقه؟","4:18":"ها إنه لا يأتمن عبيده، وإلى ملائكته ينسب حماقة،","4:19":"فكم بالحري المخلوقون من طين، الذين أساسهم في التراب، ويسحقون مثل العث؟","4:20":"يتحطمون بين صباح ومساء، ويبيدون إلى الأبد من غير أن ينتبه لهم أحد.","4:21":"ألا تنتزع منهم حبال خيامهم (أي تنطفيء شعل حياتهم) فيموتون من غير حكمة؟","5:1":"ادع الآن، فهل من مجيب؟ وإلى أي القديسين تلتفت؟","5:2":"الغيظ يقتل الأحمق، والغيرة تميت الأبله.","5:3":"لقد شاهدت الغبي يتأصل، ثم لم ألبث أن لعنت مسكنه.","5:4":"أبناؤه لا أمن لهم. يتحطمون عند الباب ولا منقذ.","5:5":"يأكل الجائع حصيدهم، ويلتهمه حتى من بين الشوك، ويمتص الظاميء ثروتهم.","5:6":"إن البلية لا تخرج من التراب، والمشقات لا تنبت من الأرض،","5:7":"ومع ذلك فإن الإنسان مولود لمعاناة المتاعب، كما ولدت الجوارح لتحلق بأجنحتها.","5:8":"لو كنت في مكانك لاتجهت إلى الله وعرضت أمري عليه.","5:9":"هو صانع عجائب لا تفحص وعظائم لا تحصى.","5:10":"يهطل الغيث على وجه الأرض، ويرسل المياه إلى الحقول.","5:11":"يقيم المتواضعين في العلى، ويرفع النائحين إلى مكان الطمأنينة.","5:12":"يبطل تدبيرات المحتالين فيخفقون،","5:13":"أو يوقع الحكماء في خدعتهم، فتتلاشى مشورة الماكرين.","5:14":"يكتنفهم ظلام في النهار، ويتحسسون طريقهم في الظهيرة، كمن يمشي في الليل.","5:15":"ينجي البائسين من سيف فمهم، ومن قبضة القوي ينقذهم،","5:16":"فيصبح للمسكين رجاء، والظلم يسد فمه.","5:17":"طوبى للرجل الذي يقومه الله ، فلا ترفض تأديب القدير.","5:18":"لأن الله يجرح ويعصب، يسحق ويداه تبرئان.","5:19":"من ست بلايا ينجيك، وفي سبع لا يقع بك أذى.","5:20":"يفديك من الموت جوعا، وفي الحرب من الموت بحد السيف.","5:21":"يقيك من لذعات اللسان، فلا تخاف من الدمار إذا أقبل.","5:22":"تسخر من الدمار والمجاعة، ولا تخشى وحوش الأرض،","5:23":"لأن عهدك مع حجارة الحقل، ووحوش الصحراء تسالمك.","5:24":"فتدرك أن خيمتك آمنة، وتتعهد حظيرتك فلا تفقد شيئا.","5:25":"عندئذ تعلم أن ذريتك كثيرة، وأن نسلك كعشب الأرض،","5:26":"وتدخل القبر في شيبة ناضجة، كما يرفع كدس القمح في موسمه.","5:27":"فانظر. هذا ما بحثنا عنه، وهو حق، فاسمعه واختبره بنفسك».","6:1":"فأجاب أيوب:","6:2":"«لو أمكن وضع حزني ومصيبتي في ميزان،","6:3":"إذن لكانا أثقل من رمل البحر، لهذا ألغو بكلامي.","6:4":"لأن سهام القدير ناشبة في، وروحي تشرب من سمها، وأهوال الله متألبة ضدي.","6:5":"أينهق الحمار الوحشي على ما لديه من عشب، أم يخور الثور على ما لديه من علف؟","6:6":"أيمكن أن يؤكل ما لا طعم له من غير ملح، أم أن هناك مذاقا لبياض البيضة؟","6:7":"لقد عافت نفسي أن تمسه لأن مثل هذا الطعام يسقمني.","6:8":"آه! ليت طلبتي تستجاب ويحقق الله رجائي،","6:9":"فيرضى الله أن يسحقني ويمد يده ويستأصلني،","6:10":"فتبقى لي تعزية وبهجة أنني في خضم آلامي لم أجحد كلام القدوس.","6:11":"ما هي قوتي حتى أنتظر؟ وما هو مصيري حتى أتصبر؟","6:12":"أقوة الحجارة قوتي؟ أم لحمي من نحاس؟","6:13":"حقا لم تعد لدي قوة لأغيث نفسي، وكل عون قد أقصي عني.","6:14":"الإنسان المكروب يحتاج إلى وفاء أصدقائه، حتى لو تخلى عن خشية القدير.","6:15":"قد غدر بي إخواني كسيل انقطع ماؤه، وكمياه الأودية العابرة،","6:16":"التي عكرها البرد حيث يختفي فيها الجليد،","6:17":"فتتلاشى في فصل الجفاف، وتختفي من مكانها عند اشتداد الحر،","6:18":"فتحيد القوافل عن طريقها وتوغل في التيه فتهلك.","6:19":"بحثت عنها قوافل تيماء، وقوافل سبأ رجت العثور عليها.","6:20":"اعترتهم الخيبة لأنهم أملوا فيها، وعندما أقبلوا إليها استبد بهم الخجل.","6:21":"والآن قد أصبحتم مثلها. أبصرتم بليتي ففزعتم.","6:22":"هل طلبت منكم شيئا، أو سألتكم أن ترشوا من مالكم من أجلي؟","6:23":"هل قلت: أنقذوني من قبضة الخصم، أو افدوني من نير العتاة؟","6:24":"علموني فأسكت، وأفهموني ما ضللت فيه.","6:25":"ما أشد وقع قول الحق، ولكن على ماذا يبرهن توبيخكم؟","6:26":"أتبغون مقارعة كلامي بالحجة، وكلمات البائس تذهب أدراج الرياح؟","6:27":"أنتم تلقون القرعة حتى على اليتيم، وتساومون على الصديق.","6:28":"والآن تلطفوا بالنظر إلي لأنني لن أكذب عليكم.","6:29":"ارجعوا، لا تكونوا حائرين، فإن أمانتي معرضة للاتهام.","6:30":"أفي لساني ظلم، أم مذاقي لا يميز ما هو فاسد؟","7:1":"أليست حياة الإنسان جهادا شاقا على الأرض، وأيامه كأيام الأجير؟","7:2":"فكما يتشوق العبد إلى الظل، والأجير يرتقب أجرته،","7:3":"هكذا كتبت علي أشهر سوء، وليالي شقاء قدرت لي.","7:4":"إذا رقدت أتساءل: متى أقوم؟ ولكن الليل طويل، وأشبع قلقا إلى الصباح.","7:5":"اكتسى لحمي بالدود وحمأة التراب، وجلدي تشقق وتقرح.","7:6":"أيامي أسرع من وشيعة النساجين، تتلاشى من غير رجاء!","7:7":"فاذكر ياالله أن حياتي ليست سوى نسمة، وأن عيني لن تعودا تريان الخير.","7:8":"إن عين من يراني الآن لن تبصرني فيما بعد، وعندما تلتفت عيناك إلي لا تجدني بعد.","7:9":"كما يضمحل السحاب ويزول، هكذا المنحدر إلى الهاوية لا يصعد،","7:10":"لا يرجع بعد إلى منزله، ومكانه لا يعرفه بعد.","7:11":"لذلك لن ألجم فمي، وسأتكلم من عمق عذاب روحي، وأشكو في مرارة نفسي.","7:12":"أبحر أنا أم تنين، حتى أقمت علي حارسا؟","7:13":"إن قلت: إن فراشي يعزيني ومرقدي يزيل كربتي،","7:14":"فأنت تروعني بالأحلام وترهبني بالرؤى.","7:15":"لذلك فضلت الاختناق والموت على جسدي هذا.","7:16":"كرهت حياتي، فلن أحيا إلى الأبد، فكف عني لأن أيامي نفخة.","7:17":"من هو الإنسان حتى تعتبره وتعيره كل اهتمام؟","7:18":"تفتقده في كل صباح وتمتحنه في كل لحظة؟","7:19":"حتى متى لا تحول وجهك عني، وتكف ريثما أبلع ريقي؟","7:20":"إن أخطأت فماذا أفعل لك يارقيب الناس؟ لماذا جعلتني هدفا لك؟ لماذا جعلتني حملا على نفسي؟","7:21":"لماذا لا تصفح عن إثمي وتزيل ذنبي، لأنني الآن أرقد في التراب، وعندما تبحث عني أكون قد فنيت».","8:1":"فأجاب بلدد الشوحي:","8:2":"«إلى متى تظل تلغو بهذه الأقوال، فتخرج من فمك كريح شديدة؟","8:3":"أيحرف الله القضاء، أم يعكس القدير ما هو حق؟","8:4":"إن كان أبناؤك أخطأوا فقد أوقع بهم جزاء معاصيهم.","8:5":"فإن أسرعت وطلبت وجه الله وتضرعت إلى القدير،","8:6":"وإن كنت نقيا صالحا، فإنه حتما يلتفت إليك ويكافئك بمسكن بر.","8:7":"وإن تكن أولاك متواضعة، فإن آخرتك تكون عظيمة جدا.","8:8":"اسأل الأجيال الغابرة، وتأمل ما اختبره الآباء،","8:9":"فإننا قد ولدنا بالأمس القريب، ولا نعرف شيئا، لأن أيامنا على الأرض ظل.","8:10":"ألا يعلمونك ويخبرونك ويبثونك ما في نفوسهم قائلين:","8:11":"أينمو البردي حيث لا مستنقع، أم تنبت الحلفاء من غير ماء؟","8:12":"إنها تيبس قبل سائر العشب، وهي في نضارتها لم تقطع.","8:13":"هكذا يكون مصير كل من ينسى الله ، وهكذا يخيب رجاء الفاجر.","8:14":"ينهار ما يعتمد عليه، ويصبح مثل بيت العنكبوت.","8:15":"يتكيء عليه فينهدم، ويتعلق به فلا يثبت.","8:16":"يزدهر كشجرة أمام الشمس، تنتشر أغصانها فوق بستانها.","8:17":"تتشابك أصوله حول كومة الحجارة، وتلتف حول الصخور.","8:18":"ولكن حالما يستأصل من موضعه ينكره مكانه قائلا: «ما رأيتك قط!»","8:19":"هكذا تكون بهجة طريقه. ولكن من التراب يأتي آخرون ويأخذون مكانه.","8:20":"إن الله لا ينبذ الإنسان الكامل ولا يمد يد العون لفاعلي الشر.","8:21":"يملأ فمك ضحكا وشفتيك هتافا،","8:22":"عندئذ يرتدي مبغضوك الخزي، وبيت الأشرار ينهار».","9:1":"فقال أيوب:","9:2":"«قد علمت يقينا أن الأمر كذلك، ولكن كيف يتبرر الإنسان أمام الله؟","9:3":"إن شاء المرء أن يتحاج معه، فإنه يعجز عن الإجابة عن واحد من ألف.","9:4":"هو حكيم القلب وعظيم القوة، فمن تصلب أمامه وسلم؟","9:5":"هو الذي يزحزح الجبال، فلا تدري حين يقلبها في غضبه.","9:6":"هو الذي يزعزع الأرض من مستقرها فتتزلزل أعمدتها.","9:7":"هو الذي يصدر أمره إلى الشمس فلا تشرق، ويختم على النجوم.","9:8":"يبسط وحده السماوات، ويمشي على أعالي البحر.","9:9":"هو الذي صنع النعش والجبار والثريا ومخادع الجنوب،","9:10":"صانع عظائم لا تستقصى وعجائب لا تحصى.","9:11":"الله يمر بي فلا أراه ويجتاز فلا أشعر به.","9:12":"إذا خطف من يرده، أو يقول له: ماذا تفعل؟","9:13":"لا يرد الله غضبه؛ تخضع له كبرياء الأشرار","9:14":"فكيف إذا يمكنني أن أجيبه، وأتخير كلماتي في مخاطبته؟","9:15":"لأني على الرغم من براءتي لا أقدر أن أجيبه، إنما أسترحم دياني.","9:16":"حتى لو دعوت واستجاب لي، فإني لا أصدق أنه قد استمع لي.","9:17":"يسحقني بالعاصفة ويكثر جروحي من غير سبب.","9:18":"لا يدعني ألتقط أنفاسي بل يشبعني مرائر.","9:19":"إن كانت القضية قضية قوة، فهو يقول متحديا: هأنذا. وإن كانت القضية قضية القضاء، فمن يحاكمه؟","9:20":"إن ظننت نفسي بريئا، فإن فمي يحكم علي، وإن كنت كاملا فإنه يجرمني.","9:21":"أنا كامل، لذا لا أبالي بنفسي، أما حياتي فقد كرهتها.","9:22":"ولكن الأمر سيان، لذلك قلت: إنه يفني الكامل والشرير على حد سواء!","9:23":"عندما تؤدي ضربات السوط إلى الموت المفاجيء يسخر من بؤس الأبرياء","9:24":"فقد عهد بالأرض إلى يد الشرير، وأعمى عيون قضاتها. إن لم يكن هو الفاعل، إذا من هو؟","9:25":"أيامي أسرع من عداء، تفر من غير أن تصيب خيرا","9:26":"تمر كسفن البردي، وكنسر ينقض على صيده.","9:27":"إن قلت: أنسى ضيقتي، وأطلق أساريري، وأبتسم وأبدي بشرا،","9:28":"فإني أظل أخشى أوجاعي، عالما أنك لن تبرئني.","9:29":"أنا مستذنب، فلماذا أجاهد عبثا؟","9:30":"وحتى لو اغتسلت بالثلج ونظفت يدي بالإشنان،","9:31":"فإنك تطرحني في مستنقع نتن حتى تكرهني ثيابي","9:32":"لأنه ليس إنسانا مثلي فأجاوبه، ونمثل معا للمحاكمة.","9:33":"وليس من حكم بيننا يضع يده على كلينا.","9:34":"ليكف عني عصاه فلا يروعني رعبه،","9:35":"عندئذ أتكلم من غير أن أخشاه، لأن نفسي بريئة مما أتهم به.","10:1":"قد كرهت حياتي، لهذا أطلق العنان لشكواي، وأتحدث عن أشجاني في مرارة نفسي،","10:2":"قائلاَ لله: لا تستذنبني. فهمني لماذا تخاصمني؟","10:3":"أيحلو لك أن تجور وتنبذ عمل يدك، وتحبذ مشورة الأشرار؟","10:4":"ألك عينا بشر، أم كنظر الإنسان تنظر؟","10:5":"هل أيامك مثل أيام الإنسان، أم سنوك في قصر سني البشر،","10:6":"حتى تبحث عن إثمي وتنقب عن خطاياي؟","10:7":"فأنت عالم أني لست مذنبا، وأنه لا منقذ من يدك.","10:8":"قد كونتني يداك وصنعتاني بجملتي، والآن التفت إلي لتسحقني!","10:9":"اذكر أنك جبلتني من طين، أترجعني بعد إلى التراب؟","10:10":"ألم تصبني كاللبن وتخثرني كالجبن؟","10:11":"كسوتني جلدا ولحما، فنسجتني بعظام وعصب.","10:12":"منحتني حياة ورحمة، وحفظت عنايتك روحي.","10:13":"كتمت هذه الأمور في قلبك، إلا أني علمت أن هذا قصدك.","10:14":"إن أخطأت فأنت تراقبني، ولا تبرئني من إثمي.","10:15":"إن أذنبت فويل لي. وإن كنت بارا لا أرفع رأسي، لأني ممتليء هوانا وناظر مذلتي،","10:16":"وإن شمخت برأسي تقتنصني كالأسد، ثم تعود فتصول علي.","10:17":"تجدد شهودك ضدي، وتضرم غضبك علي، وتؤلب جيوشا تتناوب ضدي.","10:18":"لماذا أخرجتني من الرحم؟ ألم يكن خيرا لو أسلمت الروح ولم ترني عين؟","10:19":"فأكون كأني لم أكن فأنقل من الرحم إلى القبر.","10:20":"أليست أيامي قليلة؟ كف عني لعلي أتمتع ببعض البهجة،","10:21":"قبل أن أمضي إلى حيث لا أعود، إلى أرض الظلمة وظل الموت،","10:22":"إلى أرض الظلمة المتكاثفة والفوضى، حيث الإشراق فيها كالليل البهيم».","11:1":"فأجاب صوفر النعماتي:","11:2":"«هل يترك هذا الكلام المفرط من غير جواب، أم يتبرأ الرجل المهذار؟","11:3":"أيفحم لغوك الناس، أم تهكمك يحول دون تسفيهك؟","11:4":"إذ تدعي قائلا: مذهبي صالح، وأنا بار في عيني الرب.","11:5":"ولكن ليت الله يتكلم ويفتح شفتيه ليرد عليك،","11:6":"ويكشف لك أسرار حكمته، فللحكمة الصالحة وجهان، فتدرك آنئذ أن الله عاقبك على إثمك بأقل مما تستحق.","11:7":"ألعلك تدرك أعماق الله، أم تبلغ أقصى قوة القدير؟","11:8":"هو أسمى من السماوات، فماذا يمكنك أن تفعل؟ وهو أبعد غورا من الهاوية، فماذا تعلم؟","11:9":"هو أطول من الأرض وأعرض من البحر.","11:10":"فإن اجتاز واعتقلك وحاكمك فمن يرده؟","11:11":"لأنه عالم بالمنافقين. إن رأى الإثم، أفلا ينظر في أمره؟","11:12":"يصبح الأحمق حكيما عندما يلد حمار الوحش إنسانا.","11:13":"إن هيأت قلبك وبسطت إليه يديك،","11:14":"وإن نبذت الإثم الذي تلطخت به كفاك، فلم يعد الجور يقيم في خيمتك.","11:15":"حينئذ ترفع وجهك بكرامة، وتكون راسخا من غير خوف،","11:16":"فتنسى ما قاسيت من مشقة، ولا تذكرها إلا كمياه عبرت.","11:17":"وتصبح حياتك أكثر إشراقا من نور الظهيرة، ويتحول ظلامها إلى صباح،","11:18":"وتطمئن لأن هناك رجاء، وتتلفت حولك وترقد آمنا.","11:19":"تستكين إذ ليس من مروع، وكثيرون يترجون رضاك","11:20":"أما عيون الأشرار فيصيبها التلف، ومنافذ الهرب تختفي من أمامهم، ولا أمل لهم إلا في الموت».","12:1":"فقال أيوب:","12:2":"«صحيح إنكم شعب تموت معكم الحكمة!","12:3":"إلا أني ذو فهم مثلكم، ولست دونكم معرفة، ومن هو غير ملم بهذه الأمور؟","12:4":"لقد أصبحت مثار هزء لأصدقائي، أنا الذي دعا الله فاستجاب لي. أنا الرجل البار الكامل قد أصبحت مثار سخرية!","12:5":"يضمر المطمئن شرا للبائس الذي تزل به القدم،","12:6":"بينما يسود السلام على اللصوص، وتهيمن الطمأنينة على الذين يعبدون أصناما يحملونها على أيديهم.","12:7":"ولكن اسأل البهائم فتعلمك، وطيور السماء فتخبرك،","12:8":"أو خاطب الأرض فتعرفك وسمك البحر فينبئك،","12:9":"أي منها لا يعلم أن يد الرب قد صنعت هذا؟","12:10":"ففي يده نفس كل حي وروح كل بشر.","12:11":"أليست الأذن تمتحن الكلام كما يتذوق اللسان الطعام؟","12:12":"الحكمة تلازم الشيخوخة، وفي طول الأيام فهم.","12:13":"الحكمة والقوة لله، وله المشورة والفهم.","12:14":"وما يهدمه لا يبنى، والمرء الذي يأسره الله لا يحرره إنسان.","12:15":"إن حبس المياه تجف الأرض، وإن أطلقها تغرقها.","12:16":"له العزة والحكمة. في يده المضل والمضل.","12:17":"يأسر المشيرين، ويحمق فطنة القضاة،","12:18":"يفك مناطق الملوك ويشد أحقاءهم بوثاق،","12:19":"يأسر الكهنة ويطيح بالأقوياء،","12:20":"يحرم الأمناء من الكلام ويبطل فطنة الشيوخ،","12:21":"يصيب الشرفاء بالهوان، ويرخي منطقة القوي،","12:22":"يكشف الأغوار في الظلام، ويبرز الظلمات المتكاثفة إلى النور،","12:23":"يعظم الأمم ثم يبيدها، ويوسع تخومها ثم يشتتها،","12:24":"ينزع الفهم من عقول رؤساء شعب الأرض، ثم يضلهم في قفر بلا طريق،","12:25":"فيتحسسون سبيلهم في الظلام وليس نور، ويرنحهم كالسكارى.","13:1":"هذا جميعه شهدته عيناي وسمعته أذناي وفهمته،","13:2":"وأنا أعرف ما تعرفونه أيضا، إذ لست أقل منكم فطنة.","13:3":"ولكني أريد أن أخاطب القدير، وأود أن أحاج الله .","13:4":"أما أنتم فمنافقون، وكلكم أطباء جهلة.","13:5":"ليتكم تلتزمون الصمت، فيحسب لكم ذلك حكمة.","13:6":"أنصتوا الآن إلى حجتي واصغوا إلى دعوى شفتي","13:7":"ألإرضاء الله تنطقون بالكذب، وهل من أجله تتفوهون بالبهتان؟","13:8":"أتحابون الله أم تدافعون عنه؟","13:9":"لو فحصكم هل يجد فيكم صلاحا؟ أم تخدعونه كما تخدعون البشر؟","13:10":"إنه حتما يوبخكم إن حابيتم أحدا خفية.","13:11":"أولا يرهبكم جلاله ويطغى عليكم رعبه؟","13:12":"أقوالكم أمثال رماد، وحصونكم حصون من طين.","13:13":"اسكتوا عني فأتكلم، وليحل بي ما يحل!","13:14":"لماذا أنهش لحمي بأسناني وأضع نفسي في كفي؟","13:15":"فها هو حتما يقضي علي ولا أمل لي. ومع ذلك فإني أبسط حجتي لأزكي طريقي أمامه.","13:16":"لأن هذا سبيل خلاصي، إذ لا يمثل الفاجر في حضرته.","13:17":"أرهفوا السمع لأقوالي، ولتحتفظ مسامعكم بكلماتي،","13:18":"فها أنا قد أحسنت إعداد الدعوى، ولابد أن أتبرر.","13:19":"من الذي يحاجني؟ عندئذ أصمت وأموت!","13:20":"أمرين أطلب إليك أن لا تفعلهما بي، فحينئذ لا أختفي من حضرتك:","13:21":"ارفع يديك عني ولا تدع هيبتك تفزعني،","13:22":"ثم ادع فألبي، أودعني أتكلم وأنت تجيبني.","13:23":"كم هي آثامي وخطاياي؟ أطلعني على ذنبي ومعصيتي.","13:24":"لماذا تحجب وجهك وتعاملني مثل عدو لك؟","13:25":"أتفزع ورقة متطايرة وتطارد قشا يابسا؟","13:26":"فأنت كتبت علي أمورا مرة، وأورثتني آثام صباي.","13:27":"أدخلت رجلي في المقطرة، وراقبت جميع سبلي، إذ خططت علامات على باطن قدمي،","13:28":"فأنا كشجرة نخرها السوس وكثوب أكله العث.","14:1":"الإنسان مولود المرأة. قصير العمر ومفعم بالشقاء،","14:2":"يتفتح كالزهر ثم ينتثر، ويتوارى كالشبح فلا يبقى له أثر.","14:3":"أعلى مثل هذا فتحت عينيك وأحضرتني لأتحاج معك؟","14:4":"من يستولد الطاهر من النجس؟ لا أحد!","14:5":"فإن كانت أيامه محدودة، وعدد أشهره مكتوبا لديك، وعينت أجله فلا يتجاوزه،","14:6":"فأشح بوجهك عنه ودعه يستريح مستمتعا، ريثما ينتهي يومه، كالأجير.","14:7":"لأن للشجرة أملا، إذا قطعت أن تفرخ من جديد ولا تفنى براعمها.","14:8":"حتى لو شاخت أصولها في الأرض ومات جذعها في التراب،","14:9":"فإنها حالما تستروح الماء تفرخ، وتنبت فروعا كالغرس.","14:10":"أما الإنسان فإنه يموت ويبلى، يلفظ آخر أنفاسه، فأين هو؟","14:11":"كما تنفد المياه من البحيرة، ويجف النهر،","14:12":"هكذا يرقد الإنسان ولا يقوم، ولا يستيقظ من نومه إلى أن تزول السموات.","14:13":"ليتك تواريني في عالم الأموات، وتخفيني إلى أن يعبر عني غضبك، وتحدد لي أجلا فتذكرني.","14:14":"إن مات رجل أفيحيا؟ إذن لصبرت كل أيام مكابدتي، ريثما يأتي زمن إعفائي.","14:15":"أنت تدعو وأنا أجيبك. أنت تتوق إلى عمل يديك،","14:16":"حينئذ تحصي خطواتي حقا، ولكنك لا تراقب خطيئتي،","14:17":"فتختم معصيتي في صرة، وتستر ذنبي.","14:18":"وكما يتفتت الجبل الساقط، ويتزحزح الصخر من موضعه،","14:19":"وكما تبلي المياه الحجارة، وتجرف سيولها تراب الأرض، هكذا تبيد أنت رجاء الإنسان.","14:20":"تقهره دفعة واحدة فيتلاشى، وتغير من ملامحه وتطرده.","14:21":"يكرم أبناؤه وهو لا يعلم، أو يذلون ولا يدرك ذلك.","14:22":"لا يشعر بغير آلام بدنه، ولا ينوح إلا على نفسه».","15:1":"فقال أليفاز التيماني:","15:2":"«ألعل الحكيم يجيب عن معرفة باطلة وينفخ بطنه بريح شرقية،","15:3":"فيحتج بكلام أجوف وبأقوال خرقاء؟","15:4":"أما أنت فإنك تطرح جانبا مخافة الله وتنقض عبادته.","15:5":"كلامك يقر بإثمك، وأنت تؤثر أسلوب المنافقين.","15:6":"فمك يدينك، لا أنا، شفتاك تشهدان عليك.","15:7":"ألعلك ولدت أول الناس، أو كونت قبل التلال؟","15:8":"هل تنصت في مجلس الله، فقصرت الحكمة على نفسك؟","15:9":"أي شيء تعرفه ونحن نجهله؟ وأي شيء تفهمه ونحن لا نملك إدراكه؟","15:10":"رب شيخ وأشيب بيننا أكبر سنا من أبيك.","15:11":"أيسيرة عليك تعزيات الله؟ حتى هذه الكلمات التي خوطبت بها برفق؟","15:12":"لماذا يستهويك قلبك وتتوهج عيناك،","15:13":"حتى تنفث غضبك ضد الله، ويصدر عن فمك مثل هذه الأقوال؟","15:14":"من هو الإنسان حتى يزكو أو مولود المرأة حتى يتبرر؟","15:15":"فإن كان الله لا يأتمن قديسيه، والسماوات غير طاهرة لديه،","15:16":"فكم بالأحرى يكون الإنسان الشارب الإثم كالماء مكروها وفاسدا!","15:17":"دعني أبين لك، واسمع لي لأحدثك بما رأيته،","15:18":"وبما أخبر به حكماء عن آبائهم ولم يكتموه،","15:19":"الذين لهم وحدهم وهبت الأرض ولم يدخل بينهم غريب.","15:20":"يتلوى الشرير ألما كل أيام حياته، ومعدودة هي سنو الجائر.","15:21":"يضج صوت مرعب في أذنيه، وفي أوان السلام يفاجئه المخرب.","15:22":"لا يأمل الرجوع من الظلمات، ومصيره الهلاك بالسيف.","15:23":"يهيم بحثا عن لقمة العيش، وهو يعلم أن يوم الظلمة آت وشيكا.","15:24":"يرهبه الضيق والضنك، ويطغيان عليه كملك متأهب للحرب.","15:25":"لأنه هز قبضته متحديا الله ، وعلى القدير يتجبر،","15:26":"وأغار عليه بعناد متصلف، بمجان غليظة متينة.","15:27":"ومع أنه كسا وجهه سمنا، وغشى الشحم كليتيه.","15:28":"فإنه يقيم في مدن خربة وبيوت مهجورة عتيدة أن تصبح ركاما.","15:29":"يفقد غناه، وتتبخر ثروته، ولا يثبت له في الأرض مقتنى.","15:30":"تكتنفه دائما الظلمة، وتيبس النار أغصانه، وتزيله نفخة من فم الرب.","15:31":"لا يخدعن نفسه باتكاله على السوء، لأن السوء يكون جزاءه.","15:32":"يستوفيه كاملا قبل يومه، وتكون (حياته) كسعف يابسة.","15:33":"وككرمة تساقطت عناقيد حصرمها، وتناثر زهرها كالزيتون،","15:34":"لأن جماعة الفجار عقيمون، والنار تلتهم خيام المرتشين.","15:35":"حبلوا شقاوة وأنجبوا إثما، وولدت بطونهم غشا».","16:1":"فقال أيوب:","16:2":"«قد سمعت كثيرا مثل هذا الكلام وأنتم كلكم معزون متعبون.","16:3":"أما لهذا اللغو من نهاية؟ وما الذي يثيرك حتى ترد علي؟","16:4":"في وسعي أن أتكلم مثلكم لو كنتم مكاني، وألقي عليكم أقوال ملامة، وأهز رأسي في وجوهكم،","16:5":"بل كنت أشجعكم بنصائحي، وأشددكم بتعزياتي.","16:6":"إن تكلمت لا تمحى كآبتي، وإن صمت، فماذا يخفف الصمت عني؟","16:7":"إن الله قد مزقني حقا وأهلك كل قومي.","16:8":"لقد كبلتني فصار ذلك شاهدا علي، وقام هزالي ليشهد ضدي.","16:9":"مزقني غضبه، واضطهدني. حرق علي أسنانه. طعنني عدوي بنظراته الحادة.","16:10":"فغر الناس أفواههم علي، لطموني تعييرا على خدي، وتضافروا علي جميعا.","16:11":"أسلمني الله إلى الظالم، وطرحني في يد الأشرار.","16:12":"كنت مطمئنا مستقرا، فزعزعني الرب وقبض علي من عنقي، وحطمني ونصبني له هدفا.","16:13":"حاصرني رماته وشق كليتي من غير رحمة، أهرق مرارتي على الأرض.","16:14":"اقتحمني مرة تلو مرة، وهاجمني كجبار.","16:15":"خطت مسحا على جلدي، ومرغت عزي في التراب.","16:16":"احمر وجهي من البكاء، وغشيت ظلال الموت أهدابي،","16:17":"مع أنني لم أقترف ظلما، وصلاتي مخلصة.","16:18":"ياأرض لا تستري دمي، ولا يكن لصراخي قرار.","16:19":"هوذا الآن شاهدي في السماء، وكفيلي في الأعالي","16:20":"أما أصحابي فهم الساخرون بي، لذلك تفيض دموعي أمام الله،","16:21":"لكم أحتاج لمن يدافع عني أمام الله، كما يدافع إنسان عن صديقه.","16:22":"إذ ما إن تنقضي سنوات عمري القليلة حتى أمضي في طريق لا أعود منها.","17:1":"تلفت روحي وانطفأت أيامي، والقبر معد لي.","17:2":"المستهزئون يحاصرونني، الذين تشهد عيني مشاجراتهم.","17:3":"كن لي ضامنا عند نفسك، إذ من يمكن أن يكون كفيلي؟","17:4":"فأنت حجبت الفطنة عن قلوبهم، لذلك لن تظفرهم،","17:5":"ولتتلف عيون أبناء من يشي بأصحابه طمعا في أملاكهم.","17:6":"لقد جعلني أمثولة للأمم، وصار وجهي مبصقة.","17:7":"كلت عيناي حزنا وأصبحت أعضائي كالظل،","17:8":"فزع المستقيمون من هذا، وثار البريء على الفاجر،","17:9":"أما الصديق فيتمسك بطريقه، ويزداد الطاهر اليدين قوة.","17:10":"ولكن ارجعوا جميعكم، تعالوا كلكم، فلا أجد فيكم حكيما.","17:11":"قد عبرت أيامي، وتمزقت مآربي التي هي رغبات قلبي.","17:12":"يجعلون الليل نهارا، وعلى الرغم من الظلمة يقولون: «إن النور قريب!»","17:13":"إذا رجوت أن تكون الهاوية مقرا لي، ومهدت في الظلام فراشي،","17:14":"وإن قلت للقبر أنت أبي، وللدود أنت أمي أو أختي،","17:15":"فأين إذا آمالي؟ ومن يعاين رجائي؟","17:16":"ألا تنحدر إلى مغاليق الهاوية، ونستقر معا في التراب؟»","18:1":"فقال بلدد الشوحي:","18:2":"«متى تكف عن ترديد هذه الكلمات؟ تعقل ثم نتكلم.","18:3":"لماذا تعتبرنا كالبهيمة وحمقى في عينيك؟","18:4":"يامن تمزق نفسك إربا غيظا، هل تهجر الأرض من أجلك أم تتزحزح الصخرة من موضعها؟","18:5":"أجل! إن نور الأشرار ينطفيء ولهيب نارهم لا يضيء.","18:6":"يتحول النور إلى ظلمة في خيمته، وينطفيء سراجه عليه.","18:7":"تقصر خطواته القوية وتصرعه تدبيراته،","18:8":"لأن قدميه توقعانه في الشرك وتطرحانه في حفرة،","18:9":"يقبض الفخ على عقبيه والشرك يشد عليه،","18:10":"حبالته مطمورة في الطريق، والمصيدة كامنة في سبيله،","18:11":"ترعبه أهوال من حوله وتزاحمه عند رجليه،","18:12":"قوته يلتهمها الجوع النهم، والكوارث متأهبة تترصد كبوته.","18:13":"يفترس الداء جلده ويلتهم المرض الأكال أعضاءه.","18:14":"يؤخذ من خيمته ركن اعتماده، ويساق أمام ملك الأهوال.","18:15":"يقيم في خيمته غريب ويذر كبريت على مربضه.","18:16":"تجف أصوله تحته، وتتبعثر فروعه من فوقه.","18:17":"يبيد ذكره من الأرض، ولا يبقى له اسم فيها.","18:18":"يطرد من النور إلى الظلمة، وينفى من المسكونة.","18:19":"لا يكون له نسل، ولا عقب بين شعبه، ولا حي في أماكن سكناه.","18:20":"يرتعب من مصيره أهل الغرب، ويستولي الفزع على أبناء الشرق.","18:21":"حقا تلك هي مساكن الأشرار، وهذا هو مقام من لا يعرف الله!»","19:1":"فأجاب أيوب:","19:2":"«حتى متى تعذبون نفسي وتسحقونني بالكلام الموجع؟","19:3":"فهذه عشر مرات انهلتم علي تعييرا، ولم تخجلوا من التنديد بي!","19:4":"فإن كنت حقا قد ضللت فإن أخطائي هي من شأني وحدي.","19:5":"وإن كنتم حقا تستكبرون علي وتتخذون من عاري برهانا ضدي،","19:6":"فاعلموا إذا أن الله هو الذي أوقعني في الخطأ ولف أحبولته حولي.","19:7":"ها إني أستغيث من الظلم ولا مجيب، وأهتف عاليا ولا من منصف.","19:8":"قد سيج على طريقي فلا أعبر، وخيم على سبلي بالظلمات.","19:9":"جردني من مجدي ونزع تاجي عن رأسي.","19:10":"هدمني من كل جهة، فتلاشيت، واستأصل مثل غرس رجائي.","19:11":"أضرم علي غضبه وحسبني من أعدائه.","19:12":"زحفت قواته دفعة واحدة ليمهدوا طريق حصار ضدي، وعسكروا حول خيمتي.","19:13":"أبعد عني إخوتي، فاعتزل عني معارفي.","19:14":"خذلني ذوو قرابتي ونسيني أصدقائي.","19:15":"وحسبني ضيوفي وإمائي غريبا، أصبحت في أعينهم أجنبيا.","19:16":"أدعو خادمي فلا يجيب، مع أني توسلت إليه.","19:17":"عافت زوجتي رائحة أنفاسي الخبيثة، وكرهني إخوتي فابتعدوا عني.","19:18":"حتى الصبيان يزدرونني. إذا قمت يسخرون مني.","19:19":"مقتني أصدقائي الحميمون، والذين أحببتهم انقلبوا علي.","19:20":"لصقت عظامي بجلدي ولحمي، ونجوت بجلد أسناني!","19:21":"ارفقوا بي ياأصدقائي، لأن يد الرب قد حطمتني.","19:22":"لماذا تطاردونني كما يطاردني الله ؟ ألا تشبعون أبدا من لحمي؟","19:23":"من لي بأن تدون أقوالي! ياليتها تسجل في كتاب!","19:24":"ياليتها تنقش بقلم حديد وبرصاص على صخر إلى الأبد!","19:25":"أما أنا فإني موقن أن فادي حي، وأنه لابد في النهاية أن يقوم على الأرض.","19:26":"وبعد أن يفنى جلدي، فإني بذاتي أعاين الله .","19:27":"الذي أشاهده لنفسي فتنظره عيناي وليس عينا آخر، قد فنيت كليتاي شوقا في داخلي.","19:28":"وإن قلتم ماذا نعمل لنضطهده، لأن مصدر المتاعب كامن فيه؟","19:29":"فاخشوا على أنفسكم من السيف، لأن الغيظ يجلب عقاب السيف، وتعلمون آنئذ أن هناك قضاء».","20:1":"فأجاب صوفر النعماتي:","20:2":"«إن خواطري، من جراء كلامك، تحفزني للكلام وتثيرني للرد عليك.","20:3":"سمعت توبيخا يعيرني، وأجابني روح من فطنتي.","20:4":"أما علمت هذا منذ القدم، منذ أن خلق الإنسان على الأرض،","20:5":"أن طرب الشرير إلى حين، وأن فرح الفاجر إلى لحظة؟","20:6":"مهما بلغت كبرياؤه السماوات ومست هامته الغمام،","20:7":"فإنه سيبيد كبرازه، فيتساءل الذين يعرفونه، مندهشين: أين هو؟","20:8":"يتلاشى كحلم ولا يبقى منه أثر، ويضمحل كرؤيا الليل،","20:9":"والعين التي أبصرته لا تعود تراه ثانية، ولا يعاينه مكانه فيما بعد.","20:10":"يستجدي أولاده من الفقراء، وترد يداه ثروته المسلوبة.","20:11":"(لا تجديه) حيوية عظامه لأنها تدفن في عز قوته،","20:12":"يتذوق الشر فيحلو في فمه، فيبقيه تحت لسانه،","20:13":"ويمقت أن يقذفه، بل يدخره في فمه!","20:14":"فيتحول طعامه في أمعائه إلى مرارة كالسموم.","20:15":"ويتقيأ ما ابتلعه من أموال، ويستخرجها الله من جوفه.","20:16":"لقد رضع سم الصل، فقتله لسان الأفعى.","20:17":"لن تكتحل عيناه بمرأى الأنهار الجارية، ولا بالجداول الفياضة بالعسل والزبد.","20:18":"يرد ثمار تعبه ولا يبلعه ولا يستمتع بكسب تجارته.","20:19":"لأنه هضم حق الفقراء وخذلهم وسلب بيوتا لم يبنها.","20:20":"وإذ لا يعرف طمعه قناعة، فإنه لن يدخر شيئا يستمتع به.","20:21":"لم يبق نهمه على شيء، لذلك لن يدوم خيره.","20:22":"في وفرة سعته يصيبه الضنك، وتحل به أقسى الكوارث.","20:23":"وعندما يملأ بطنه ينفث عليه الله غضبه الحارق ويمطره عليه طعاما له.","20:24":"إن فر من آلة حرب من حديد، تخترقه قوس النحاس.","20:25":"اخترقته عميقا وخرجت من جسده، ونفذ حدها اللامع من مرارته، وحل به رعب.","20:26":"كل ظلمة تتربص بذخائره، وتأكله نار لم تنفخ، وتلتهم ما بقي من خيمته.","20:27":"تفضح السماوات إثمه، وتتمرد الأرض عليه،","20:28":"تفنى مدخرات بيته وتحترق في يوم غضب الرب.","20:29":"هذا هو المصير الذي يعده الله للأشرار، والميراث الذي كتبه الله لهم».","21:1":"فقال أيوب:","21:2":"«استمعوا سمعا إلى أقوالي، ولتكن لي هذه تعزية منكم.","21:3":"احتملوني فأتكلم، ثم اسخروا مني.","21:4":"هل شكواي هي ضد إنسان؟ وإن كانت، فلماذا لا أكون ضيق الخلق؟","21:5":"تفرسوا في واندهشوا، وضعوا أيديكم على أفواهكم.","21:6":"عندما أفكر في الأمر أرتاع، وتعتري جسدي رعدة.","21:7":"لماذا يحيا الأشرار ويطعنون في السن ويزدادون قوة؟","21:8":"ذريتهم تتأصل أمامهم، ونسلهم يتكاثرون في أثناء حياتهم.","21:9":"بيوتهم آمنة من المخاوف، وعصا الله لا تنزل عليهم.","21:10":"ثورهم يلقح ولا يخفق، وبقرتهم تلد ولا تسقط.","21:11":"يسرحون صبيانهم كسرب، وأطفالهم يرقصون.","21:12":"يغنون بالدف والعود ويطربون لصوت المزمار،","21:13":"يقضون أيامهم في الرغد، ثم في لحظة يهبطون إلى الهاوية.","21:14":"يقولون للرب: فارقنا فإننا لا نعبأ بمعرفة طرقك.","21:15":"من هو القدير حتى نعبده؟ وأي كسب نجنيه إن صلينا إليه؟","21:16":"ولكن فلاحهم ليس في أيديهم، لذلك تظل مشورة الأشرار بعيدة عني.","21:17":"كم مرة ينطفيء مصباح الأشرار؟ وكم مرة تتوالى عليهم النكبات، إذ يقسم الله لهم نصيبا في غضبه؟","21:18":"يصبحون كالتبن في وجه الريح، وكالعصافة التي تطوح بها الزوبعة.","21:19":"أنتم تقولون: إن الله يدخر إثم الشرير لأبنائه، لا! إنه ينزل العقاب بالأثيم نفسه، فيعلم.","21:20":"فليشهد هلاكه بعينيه، وليجرع غصص غضب القدير.","21:21":"إذ ما بغيته من بيته بعد فنائه، وقد بتر عدد شهور حياته؟","21:22":"أهناك من يلقن الله علما، وهو الذي يدين المتشامخين؟","21:23":"قد يموت المرء في وفرة رغده، وهو ينعم بالدعة والطمأنينة،","21:24":"والعافية تكسو جنبيه، ومخ عظامه طريء.","21:25":"وقد يموت آخر بمرارة نفس ولم يذق خيرا","21:26":"غير أن كليهما يواريهما التراب ويغشاهما الدود.","21:27":"انظروا، أنا مطلع على أفكاركم وما تتهمونني به جورا،","21:28":"لأنكم تقولون: أين هو منزل الرجل العظيم، وأين هي خيام الأشرار المقيمين فيها؟","21:29":"هلا سألتم عابري السبيل؟ ألا تكترثون لشهادتهم؟","21:30":"إن الشرير قد أفلت من يوم البوار، ونجا من العقاب في يوم الغضب.","21:31":"فمن يواجهه بسوء أعماله، ومن يدينه على رداءة تصرفاته؟","21:32":"عندما يوارى في قبره يقوم حارس على ضريحه.","21:33":"تطيب له تربة الوادي، ويمشي خلفه جمهور غفير، والذين يتقدمونه لا يحصى لهم عدد.","21:34":"فكيف، بعد هذا، تعزونني بلغو الكلام؟ لم يبق من أجوبتكم إلا كل ما هو باطل».","22:1":"فأجاب أليفاز التيماني:","22:2":"«أينفع الإنسان الله ؟ إنما الحكيم ينفع نفسه!","22:3":"هل برك مدعاة لمسرة القدير؟ وأي كسب له إن كنت زكيا؟","22:4":"أمن أجل تقواك يوبخك ويدخل في محاكمة معك؟","22:5":"أو ليس إثمك عظيما؟ أو ليست خطاياك لا متناهية؟","22:6":"لقد ارتهنت أخاك بغير حق، وجردت العراة من ثيابهم.","22:7":"لم تسق المعيي ماء، ومنعت عن الجائع طعامك.","22:8":"صاحب القوة استحوذ على الأرض، وذو الحظوة أقام فيها.","22:9":"أرسلت الأرامل فارغات وحطمت أذرع اليتامى،","22:10":"لذلك أحدقت بك الفخاخ وطغى عليك رعب مفاجيء.","22:11":"اظلم نورك فلم تعد تبصر، وغمرك فيضان ماء.","22:12":"أليس الله في أعالي السماوات، يعاين النجوم مهما تسامت؟","22:13":"ومع هذا فأنت تقول: ماذا يعلم الله ؟ أمن خلف الضباب يدين؟","22:14":"إن الغيوم المتكاثفة تغلفه فلا يرى، وعلى قبة السماء يخطو.","22:15":"هل تظل ملتزما بالسير في الطريق التي سلكها الأشرار؟","22:16":"الذين قرضوا قبل أوانهم، وجرفوا من أساسهم،","22:17":"قائلين لله: فارقنا. وماذا في وسع الله أن يفعل بهم؟","22:18":"مع أن الله غمر بيوتهم بالخيرات، فلتبعد عني مشورة الأشرار.","22:19":"يشهد الصديقون (عقاب الأشرار) ويفرحون، والأبرياء يستهزئون قائلين:","22:20":"قد باد مقاومونا، وما تبقى منهم التهمته النيران.","22:21":"استسلم إلى الله، وتصالح معه فيصيبك خير.","22:22":"تقبل الشريعة من فمه، وأودع كلامه في قلبك.","22:23":"إن رجعت إلى القدير واتضعت، وإن طرحت الإثم بعيدا عن خيامك،","22:24":"ووضعت ذهبك في التراب، وتبر أوفير بين حصى الوادي،","22:25":"وإن أصبح القدير ذهبك وفضتك الثمينة،","22:26":"عندئذ تتلذذ نفسك بالقدير، ويرتفع وجهك نحو الله.","22:27":"تصلي إليه فيستجيب، وتوفي نذورك،","22:28":"ويتحقق لك ما تعزم عليه من أمر، ويضيء نور على سبلك","22:29":"حقا إن الله يذل المتكبرين وينقذ المتواضعين،","22:30":"وينجي حتى المذنب بفضل طهارة قلبك».","23:1":"عندئذ أجاب أيوب:","23:2":"«إن شكواي اليوم مرة، ولكن اليد التي علي أثقل من أنيني.","23:3":"أين لي أن أجده فأمثل أمام كرسيه،","23:4":"وأعرض عليه قضيتي وأملأ فمي حججا،","23:5":"فأطلع على جوابه وأفهم ما يقوله لي؟","23:6":"أيخاصمني بعظمة قوته؟ لا! بل يلتفت مترئفا علي.","23:7":"هناك يمكن للمستقيم أن يحاجه، وأبريء ساحتي إلى الأبد من قاضي.","23:8":"ولكن ها أنا أتجه شرقا فلا أجده، وإن قصدت غربا لا أشعر به،","23:9":"أطلبه عن شمالي فلا أراه وألتفت إلى يميني فلا أبصره.","23:10":"ولكنه يعرف الطريق الذي أسلكه، وإذا امتحنني أخرج كالذهب","23:11":"اقتفت قدماي إثر خطاه، وسلكت بحرص في سبله ولم أحد.","23:12":"لم أتعد على وصاياه، وذخرت في قلبي كلماته.","23:13":"ولكنه متفرد وحده فمن يرده؟ يفعل ما يشاء،","23:14":"لأنه يتمم ما رسمه لي، ومازال لديه وفرة منها.","23:15":"لذلك أرتعب في حضرته، وعندما أتأمل، يخامرني الخوف منه.","23:16":"فقد أضعف الله قلبي، وروعني القدير.","23:17":"ومع ذلك لم تسكنني الظلمة، ولا الدجى غشى وجهي.","24:1":"لماذا إذا لم يحدد القدير أزمنة المحاكمة، ولماذا لا يرى متقوه يومه؟","24:2":"ينقل الناس التخوم، ويغتصبون القطعان ويرعونها.","24:3":"يأخذون حمار الأيتام ويرتهنون ثور الأرملة.","24:4":"يصدون المساكين عن الطريق، فيختبيء فقراء الأرض جميعا.","24:5":"انظروا فها هم يخرجون إلى عملهم كالحمار الوحشي في الصحراء يطلبون في القفر صيدا، ليكون طعاما لأبنائهم،","24:6":"يجمعون علفهم من الحقل ويقطفون كرم الشرير.","24:7":"يرقدون الليل كله عراة من غير كسوة تقيهم غائلة البرد.","24:8":"يبتلون من مطر الجبال، ويركنون إلى الصخر لافتقارهم إلى المأوى.","24:9":"يخطفون اليتامى عن الثدي، ويرتهنون طفل المسكين،","24:10":"يطوفون عراة بلا كساء، جياعا حاملين الحزم.","24:11":"يعصرون الزيت بين أتلام زيتون الأشرار، ويدوسون معاصر الخمر وهم عطاش.","24:12":"يرتفع من المدن أنين المشرفين على الموت، وتستغيث نفوس الجرحى، والله لا يصغي إلى دعائهم.","24:13":"هناك من كان بين المتمردين على النور، فلم يعرفوا طرقه، ولم يمكثوا في سبله.","24:14":"عند مطلع النور ينهض القاتل ويهلك البائس والمحتاج، وفي الليل يغدو لصا.","24:15":"ينتظر الزاني حلول العتمة فيتقنع قائلا: لن تبصرني عين.","24:16":"ينقبون البيوت ليلا، وفي النهار يغلقون على أنفسهم فلا يعرفون النور،","24:17":"لأن الصباح عندهم كظل الموت، وأهوال الظلمة هي رفقتهم.","24:18":"ينجرفون لخفتهم على وجه المياه، ونصيبهم ملعون في الأرض، ولا أحد يتوجه نحو كرومهم.","24:19":"وكما أن القحط والقيظ يذهبان بمياه الثلج، كذلك تذهب الهاوية بالخاطيء،","24:20":"تنساه الرحم ويستطيبه الدود، ولا أحد يذكر الأشرار فيما بعد، فيكونون كشجرة مقتلعة.","24:21":"يسيئون إلى العاقر التي لم تلد، ولا يحسنون إلى الأرملة.","24:22":"الله في جلاله يدمر القوي ويميته.","24:23":"يمنحهم طمأنينة تركن إليها قلوبهم إلى حين، لكن عينيه تراقبان طرقهم.","24:24":"تشامخوا للحظة ثم تلاشوا، انحطوا وجمعوا كالأشياء الأخرى، بل حصدوا كرؤوس السنابل؛","24:25":"وإلا، من يقدر أن يكذبني ويجعل كلامي كالعدم؟»","25:1":"فقال بلدد الشوحي:","25:2":"«لله السلطان والهيبة، يصنع السلام في أعاليه.","25:3":"هل من إحصاء لأجناده، وعلى من لا يشرق نوره؟","25:4":"فكيف يتبرر الإنسان عند الله، وكيف يزكو مولود المرأة؟","25:5":"فإن كان القمر لا يضيء، والكواكب غير نقية في عينيه،","25:6":"فكم بالحري الإنسان الرمة وابن آدم الدود؟»","26:1":"فأجاب أيوب:","26:2":"«يالكم من عون كبير للخائر! كيف خلصتم ذراعا واهية!","26:3":"أية مشورة أسديتم للأحمق! أية معرفة صادقة وافرة زودتموه بها!","26:4":"لمن نطقتم بالكلمات؟ وروح من عبرتم عنه؟","26:5":"ترتعد الأشباح من تحت، وكذلك المياه وسكانها.","26:6":"الهاوية مكشوفة أمام الله والهلاك لا ستر له.","26:7":"يمد الشمال على الخواء ويعلق الأرض على لا شيء.","26:8":"يصر المياه في سحبه فلا يتخرق الغيم تحتها.","26:9":"يحجب وجه عرشه ويبسط فوقه غيومه.","26:10":"رسم حدا على وجه المياه عند خط اتصال النور بالظلمة.","26:11":"من زجره ترتعش أعمدة السماء وترتعد من تقريعه.","26:12":"بقوته يهديء هيجان البحر وبحكمته يسحق رهب.","26:13":"بنسمته جمل السماوات، ويداه اخترقتا الحية الهاربة.","26:14":"وهذه ليست سوى أدنى طرقه، وما أخفت همس كلامه الذي نسمعه؛ فمن يدرك إذا رعد جبروته؟»","27:1":"واستطرد أيوب يضرب مثله قائلا:","27:2":"«حي هو الله الذي نزع حقي، والقدير الذي أمر حياتي،","27:3":"ولكن مادامت نسمتي في، ونفخة الله في أنفي،","27:4":"فإن شفتي لن تنطقا بالسوء، ولساني لن يتلفظ بالغش.","27:5":"حاشا لي أن أقر بصواب أقوالكم، ولن أتخلى عن كمالي حتى الموت.","27:6":"أتشبث ببري ولن أرخيه، لأن ضميري لا يؤنبني على يوم من أيامي.","27:7":"ليكن عدوي نظير الشرير، ومقاومي كالفاجر،","27:8":"إذ ما هو رجاء الفاجر عندما يستأصله الله ويزهق أنفاسه؟","27:9":"هل يستمع الله إلى صرخته إذا حل به ضيق؟","27:10":"هل يسر بالقدير ويستغيث به في كل الأزمنة؟","27:11":"إني أعلمكم عن قوة الله، ولا أكتم عنكم ما لدى القدير.","27:12":"فأنتم جميعا قد عاينتم ذلك بأنفسكم، فما بالكم تنطقون بالباطل قائلين:","27:13":"هذا هو نصيب الشرير عند الله والميراث الذي يناله الظالم من القدير.","27:14":"إن تكاثر بنوه فليكونوا طعاما للسيف، ونسله لا يشبع خبزا.","27:15":"ذريته تموت بالوبأ، وأراملهم لا تنوح عليهم.","27:16":"إن جمع فضته كأكوام التراب، وكوم ملابس كالطين،","27:17":"فإن ما يعده من ثياب يرتديه الصديق، والبريء يوزع الفضة.","27:18":"يبني بيته كبيت العنكبوت، أو كمظلة صنعها حارس الكروم.","27:19":"يضطجع غنيا ويستيقظ معدما. يفتح عينيه وإذا بثروته قد تلاشت.","27:20":"يطغى عليه رعب كفيضان، وتخطفه في الليل زوبعة.","27:21":"تطوح به الريح الشرقية فيختفي وتقتلعه من مكانه.","27:22":"تطبق عليه من غير رحمة وهو هارب من وجه عنفوانها.","27:23":"تصفر الريح عليه، وترعبه بقوتها المدمرة.","28:1":"لا ريب أن هناك منجما للفضة وبوتقة لتمحيص الذهب.","28:2":"يستخرج الحديد من التراب، ومن المعدن الخام يصهر النحاس.","28:3":"قد وضع الإنسان حدا للظلمة، وبحث في أقصى طرف عن المعدن في الظلمات العميقة.","28:4":"حفروا منجما بعيدا، في موضع مقفر من السكان، هجرته أقدام الناس، وتدلوا فيه.","28:5":"أما الأرض التي تنبت لنا خيرا فقد انقلب أسفلها كما بنار.","28:6":"يكمن في صخورها الياقوت الأزرق، وفي ترابها الذهب.","28:7":"لم يهتد إلى طريقها طير جارح، ولم تبصره عين باشق.","28:8":"لم تطأه أقدام الضواري أو يسلك فيه الليث.","28:9":"امتدت أيديهم إلى الصوان، وقلبوا الجبال من أصولها.","28:10":"حفروا ممرات في صخورها، وعاينت أعينهم كل ثمين.","28:11":"سدوا مجاري الأنهار، وأبرزوا مكنونات قيعانها إلى النور.","28:12":"ولكن أين توجد الحكمة؟ وأين مقر الفطنة؟","28:13":"لا يدرك الإنسان قيمتها، ولا يمكن أن توجد في أرض الأحياء.","28:14":"يقول الغمر: ليست هي في؛ ويقول البحر إني لا أملكها.","28:15":"لا تقايض بالذهب الخالص، ولا توزن الفضة ثمنا لها.","28:16":"لا تثمن بذهب أوفير أو بالجزع الكريم أو بالياقوت الأزرق.","28:17":"لا يعادلها ذهب أو زجاج، ولا تستبدل بمجوهرات من الذهب الخالص.","28:18":"لا يذكر معها المرجان أو البلور، فثمن الحكمة أغلى من كل اللآليء.","28:19":"لا يقارن بها ياقوت كوش ولا تثمن بالذهب النقي.","28:20":"إذا من أين تأتي الحكمة، وأين هو مقر الفطنة؟","28:21":"إنها محجوبة عن عيني كل حي، وخافية عن طير السماء.","28:22":"الهلاك والموت قالا: قد بلغت مسامعنا شائعة عنها.","28:23":"الله وحده يعلم الطريق إليها ويعرف مقرها،","28:24":"لأنه يرى أقصى الأرض ويحيط بجميع ما تحت السماوات.","28:25":"عندما جعل للريح وزنا وعاير المياه بمقياس،","28:26":"عندما وضع سننا للمطر وممرا لصواعق الرعود،","28:27":"آنئذ رآها وأذاع خبرها وأثبتها وفحصها،","28:28":"ثم قال للإنسان: انظر، إن مخافة الرب هي الحكمة، وتفادي الشر هو الفطنة».","29:1":"واستطرد أيوب في ضرب مثله:","29:2":"«ياليتني مازلت كما كنت في الشهور الغابرة، في الأيام التي حفظني فيها الله ،","29:3":"حين كان مصباحه يضيء فوق رأسي، فأسلك عبر الظلمة في نوره.","29:4":"يوم كنت في ريعان قوتي ورضى الله مخيما فوق بيتي.","29:5":"وا لقدير ما برح معي، وأولادي مازالوا حولي.","29:6":"حين كنت أغسل خطواتي باللبن، والصخر يفيض لي أنهارا من الزيت.","29:7":"حين كنت أخرج إلى بوابة المدينة، وأحتل في الساحة مجلسي،","29:8":"فيراني الشبان ويتوارون، ويقف الشيوخ احتراما لي.","29:9":"يمتنع العظماء عن الكلام ويضعون أيديهم على أفواههم.","29:10":"يتلاشى صوت النبلاء، وتلتصق ألسنتهم بأحناكهم.","29:11":"إذا سمعت لي الأذن تطوبني، وإذا شهدتني العين تثني علي،","29:12":"لأ ني أنقذت البائس المستغيث، وأجرت اليتيم طالب العون،","29:13":"فحلت علي بركة المشرف على الموت، وجعلت قلب الأرملة يتهلل فرحا.","29:14":"ارتديت البر فكساني، وكجبة وعمامة كان عدلي.","29:15":"كنت عيونا للأعمى، وأقداما للأعرج،","29:16":"وكنت أبا للمسكين، أتقصى دعوى من لم أعرفه.","29:17":"هشمت أنياب الظالم ومن بين أسنانه نزعت الفريسة،","29:18":"ثم حدثت نفسي: إني سأموت في خيمتي وتتكاثر أيامي كحبات الرمل.","29:19":"ستمتد أصولي إلى المياه، والطل يبيت على أغصاني.","29:20":"يتجدد مجدي دائما، وقوسي أبدا جديدة في يدي.","29:21":"يستمع الناس لي وينتظرون، ويصمتون منصتين لمشورتي.","29:22":"بعد كلامي لا يثنون على أقوالي، وحديثي يقطر عليهم كالندى.","29:23":"يترقبونني كالغيث، ويفتحون أفواههم كمن ينهل من مطر الربيع","29:24":"إن ابتسمت لهم لا يصدقون، ونور وجهي لم يطرحوه عنهم بعيدا.","29:25":"أختار لهم طريقهم وأتصدر مجلسهم، وأكون بينهم كملك بين جيوشه، وكا لمعزي بين النائحين.","30:1":"أما الآن فقد هزأ بي من هم أصغر مني سنا، ممن كنت آنف أن أجعل آباءهم مع كلاب غنمي.","30:2":"إذ ما جدوى قوة أيديهم لي بعد أن نضب عنفوانهم؟","30:3":"يهيمون هزالى جياعا، ينبشون اليابسة الخربة المهجورة.","30:4":"يلتقطون الملاح بين العليق، وخبزهم عروق الرتم.","30:5":"يطردون من بين الناس، ويصرخون خلفهم كما يصرخون على لص.","30:6":"يقيمون في كهوف الوديان الجافة، بين الصخور وفي ثقوب الأرض.","30:7":"ينهقون بين العليق، ويربضون تحت العوسج.","30:8":"هم حمقى، أبناء قوم خاملين منبوذين من الأرض.","30:9":"أما الآن فقد أصبحت مثار سخرية لهم ومثلا يتندرون به","30:10":"يشمئزون مني ويتجافونني، لا يتوانون عن البصق في وجهي!","30:11":"لأن الله قد أرخى وتر قوسي وأذلني، انقلبوا ضدي بكل قوتهم.","30:12":"قام صغارهم عن يميني يزلون قدمي ويمهدون سبل دماري.","30:13":"سدوا علي منفذ مهربي، وتضافروا على هلاكي، من غير أن يكون لي معين.","30:14":"وكأنما من ثغرة واسعة تدافعوا نحوي، واندفعوا هاجمين بين الردم.","30:15":"طغت علي الأهوال، فتطايرت كرامتي كورقة أمام الريح، ومضى رغدي كالسحاب.","30:16":"والآن تهافتت نفسي علي وتناهبتني أيام بؤسي.","30:17":"ينخر الليل عظامي، وآلامي الضارية لا تهجع.","30:18":"تشد بعنف لباسي وتحزمني مثل طوق عباءتي.","30:19":"قد طرحني الله في الحمأة فأشبهت التراب والرماد.","30:20":"أستغيث بك فلا تستجيب، وأقف أمامك فلا تأبه بي.","30:21":"أصبحت لي عدوا قاسيا، وبقدرة ذراعك تضطهدني.","30:22":"خطفتني وأركبتني على الريح، تذيبني في زئير العاصفة.","30:23":"فأيقنت أنك تسوقني إلى الموت، وإلى دار ميعاد كل حي.","30:24":"ولكن ألا يمد إنسان يده من تحت الأنقاض؟ أو لا يستغيث في بليته؟","30:25":"ألم أبك لمن قسا عليه يومه؟ ألم تحزن نفسي للمسكين؟","30:26":"ولكن حين ترقبت الخير أقبل الشر، وحين توقعت النور هجم الظلام.","30:27":"قلبي يغلي ولن يهدأ، وأيام البلية غشيتني.","30:28":"فأمضي نائحا لكن من غير عزاء. أقف بين الناس أطلب العون.","30:29":"صرت أخا لبنات آوى، ورفيقا للنعام.","30:30":"اسود جلدي علي وتقشر، واحترقت عظامي من الحمى","30:31":"صارت قيثارتي للنوح، ومزماري لصوت النادبين.","31:1":"أبرمت عهدا مع عيني، فكيف أرنو إلى عذراء؟","31:2":"وماذا يكون نصيبي عند الله من فوق، وما هو إرثي من عند القدير في الأعالي؟","31:3":"أليست البلية من حظ الشرير، والكارثة من نصيب فاعلي الإثم؟","31:4":"ألا يرى الله طرقي ويحصي كل خطواتي؟","31:5":"إن سلكت في ضلال وأسرعت قدمي لارتكاب الغش،","31:6":"فلأوزن في قسطاس العدل، وليعرف الله كمالي.","31:7":"إن حادت خطواتي عن الطريق، وغوى قلبي وراء عيني، وعلقت بيدي لطخة عار،","31:8":"فلأزرع أنا وآخر يأكل، وليستأصل محصولي.","31:9":"إن هام قلبي وراء امرأة، أو طفت عند باب جاري،","31:10":"فلتطحن زوجتي لآخر، وليضاجعها آخرون.","31:11":"لأن هذه رذيلة وإثم يعاقب عليه القضاة،","31:12":"ونار ملتهمة تفضي إلى الهلاك وتقضي على غلاتي.","31:13":"إن كنت قد تنكرت لحق خادمي وأمتي عندما اشتكيا علي،","31:14":"فماذا أصنع عندما يقوم الله (لمحاكمتي)؟ وبماذا أجيب عندما يتقصى (ليحاسبني)؟","31:15":"أليس الذي كونني في الرحم كونه أيضا؟ أو ليس الذي شكلنا في الرحم واحد؟","31:16":"إن كنت قد منعت عن المسكين ما يطلبه، أو أوهنت عيني الأرملة من فرط البكاء،","31:17":"أو أكلت كسرة خبزي وحدي ولم أتقاسمها مع اليتيم،","31:18":"إذ منذ حداثتي رعيته كأب، وهديته من رحم أمه.","31:19":"إن كنت قد رأيت أحدا مشرفا على الهلاك من العري، أو مسكينا من غير كساء،","31:20":"إن لم تباركني حقواه المستدفئتان بجزة غنمي!","31:21":"إن كنت قد رفعت يدي ضد اليتيم، مستغلا نفوذي في القضاء،","31:22":"فليسقط عضدي من كتفي، ولتنكسر ذراعي من قصبتها.","31:23":"لأنني أرتعب من نقمة الله، وما كنت أقوى على مواجهة جلاله.","31:24":"إن كنت قد جعلت الذهب متكلي، أو قلت للإبريز أنت معتمدي،","31:25":"إن كنت قد اغتبطت بعظم ثروتي، أو لأن يدي فاضتا بوفرة الكسب،","31:26":"إن كنت قد نظرت إلى الشمس حين أضاءت، أو إلى القمر السائر ببهاء،","31:27":"فغوي قلبي سرا وقبلت يدي توقيرا لهما،","31:28":"فإن هذا أيضا إثم يعاقب عليه القضاة، لأني أكون قد جحدت الله العلي.","31:29":"إن كنت قد فرحت بدمار مبغضي أو شمت حين أصابه شر،","31:30":"لا! لم أدع لساني يخطيء بالدعاء على حياته بلعنة.","31:31":"إن كان أهل خيمتي لم يقولوا: أهناك من لم يشبع من طعام أيوب؟","31:32":"فالغريب لم يبت في الشارع لأني فتحت أبوابي لعابري السبيل.","31:33":"إن كنت قد كتمت آثامي كبقية الناس، طاويا ذنوبي في حضني،","31:34":"رهبة من الجماهير الغفيرة، وخوفا من إهانة العشائر، وصمت واعتصمت داخل الأبواب.","31:35":"آه من لي بمن يستمع لي! هوذا توقيعي، فليجبني القدير. ليت خصمي يكتب شكواه ضدي،","31:36":"فأحملها على كتفي وأعصبها تاجا لي،","31:37":"لكنت أقدم له حسابا عن كل خطواتي، وأدنو منه كما أدنو من أمير.","31:38":"إن كانت أرضي قد احتجت علي وتباكت أتلامها جميعا،","31:39":"إن كنت قد أكلت غلاتها بلا ثمن، أو سحقت نفوس أصحابها،","31:40":"فلينبت فيها الشوك بدل الحنطة والزوان بدل الشعير» تمت هنا أقوال أيوب.","32:1":"فكف هؤلاء الرجال عن الرد على أيوب، لأنه كان مقتنعا ببراءة نفسه.","32:2":"غير أن غضب أليهو بن برخئيل البوزي، من عشيرة رام، احتدم على أيوب، لأنه ظن نفسه أبر من الله،","32:3":"كما غضب أيضا على أصحاب أيوب الثلاثة، لأنهم عجزوا عن الرد عليه، مع أنهم استذنبوه.","32:4":"وكان أليهو قد لزم الصمت حتى فرغوا من الكلام مع أيوب، لأنهم كانوا أكبر منه سنا.","32:5":"ولما رأى أليهو أن الرجال الثلاثة قد أخفقوا في إجابة أيوب قال بغضب محتدم:","32:6":"«أنا صغير السن وأنتم شيوخ، لذلك تهيبت وخفت أن أبدي لكم رأيي،","32:7":"قائلا لنفسي: لتتكلم الأيام، ولتلقن كثرة السنين حكمة»","32:8":"ولكن الروح الذي في الإنسان، ونسمة القدير، تعطي الإنسان فهما.","32:9":"ليس المسنون وحدهم هم الحكماء، ولا الشيوخ فقط يدركون الحق.","32:10":"لذلك أقول: أصغوا إلي لأحدثكم بما أعرف.","32:11":"لقد أنصت بصبر حين تكلمتم، واستمعت إلى حججكم حين بحثتم عن الكلام،","32:12":"وأوليتكم انتباهي، فلم أجد في كلامكم ما أفحم أيوب، أو رد على أقواله.","32:13":"احترسوا لئلا تقولوا إننا قد أحرزنا حكمة، فالرب يفحم أيوب لا الإنسان.","32:14":"إنه لم يوجه حديثه إلي، لذلك لن أجيبه بمثل كلامكم.","32:15":"لقد تحيروا، ياأيوب، ولم يجيبوا إذ أعياهم النطق،","32:16":"فهل أصمت لأنهم لم يتكلموا، وهل أمتنع عن الرد؟","32:17":"لا، سأجيب أنا أيضا وأبدي رأيي،","32:18":"لأني أفيض كلاما، والروح في داخلي يحفزني.","32:19":"انظروا، إن قلبي في داخلي كخمر لم تفتح، وكزقاق جديدة تكاد تنشق!","32:20":"فلأتكلمن لأفرج عن نفسي، أفتح شفتي لأجيب.","32:21":"لن أحابي إنسانا أو أتملق أحدا.","32:22":"لأني لا أعرف التملق، وإلا يقضي علي صانعي سريعا.","33:1":"والآن ياأيوب اصغ إلى أقوالي، واسمع كلامي كله:","33:2":"ها أنا قد فتحت فمي فنطق لساني في حنكي،","33:3":"كلماتي تصدر من قلب مستقيم، وشفتاي تتحدثان بإخلاص بما أعلم.","33:4":"روح الله هو الذي كونني، ونسمة القدير أحيتني،","33:5":"فأجبني إن كنت تستطيع. أحسن الدعوى، واتخذ لك موقفا.","33:6":"إنما أنا نظيرك أمام الله، من الطين جبلت،","33:7":"فلا هيبتي تخيفك، ولا يدي ثقيلة عليك.","33:8":"حقا قد تكلمت في أذني فاستمعت إلى أقوالك.","33:9":"أنت قلت: أنا نقي بريء من كل ذنب، أنا طاهر لا إثم في،","33:10":"إنما الله يتربص بي ليجد علة علي ويحسبني عدوا له،","33:11":"يضع أقدامي في المقطرة، ويترصد سبلي.","33:12":"ولكنك مخطيء في هذا، وأنا الذي أجيبك. إن الله أعظم من الإنسان،","33:13":"فما بالك تخاصمه قائلا: إنه لن يجيب عن تساؤلاتي؟","33:14":"إن الله يتكلم بطريقة أو بأخرى وإن كان الإنسان لا يدركها.","33:15":"يتكلم في حلم، في رؤيا الليل عندما يغشى الناس سبات عميق.","33:16":"عندئذ يفتح آذان الناس ويرعبهم بتحذيراته،","33:17":"ليصرف الإنسان عن خطيئته ويستأصل منه الكبرياء،","33:18":"لينقذ نفسه من الهاوية وحياته من الهلاك بحد السيف.","33:19":"قد يقوم الإنسان بالألم على مضجعه، وبالأوجاع الناشبة في عظامه،","33:20":"حتى تعاف حياته الطعام، وشهيته لذيذ المأكل.","33:21":"يبلى لحمه فيختفي عن العيان، وتنبري عظامه التي كانت خافية من قبل.","33:22":"تدنو نفسه من الهاوية، وحياته من زبانية الموت.","33:23":"إن وجد له ملاك، شفيع، واحد من بين ألف، ليعلن للإنسان ما هو صالح له،","33:24":"يترَأف عليه قائلا: أنقذه يارب من الانحدار إلى الهاوية، فقد وجدت له فدية.","33:25":"فيصير لحمه أكثر غضاضة من أيام صباه ويعود إلى عهد ريعان شبابه","33:26":"عندئذ يدعو المرء الله فيرضى عنه، ويمثل في حضرته بفرح، ويرد له الله بره،","33:27":"ثم يرنم أمام الناس قائلا: لقد أخطأت وحرفت ما هو حق ولم أجاز عليه،","33:28":"قد افتدى الله حياتي من الانحدار إلى الهاوية، فتنتعش حياتي لترى النور.","33:29":"هذا كله يجريه الله على الإنسان مرتين وثلاث مرات،","33:30":"ليرد نفسه عن الهاوية ليستضيء بنور الحياة.","33:31":"فاصغ ياأيوب وأنصت إلي. اصمت ودعني أتكلم.","33:32":"وإن كان لديك ما تقوله فأجبني، تكلم، فإني أرغب في تبريرك.","33:33":"وإلا فاصغ إلي، أنصت فأعلمك الحكمة».","34:1":"وأضاف أليهو قائلا:","34:2":"«استمعوا إلى أقوالي أيها الحكماء، وأصغوا إلي ياذوي المعرفة،","34:3":"لأن الأذن تمحص الأقوال كما يتذوق الحنك الطعام.","34:4":"لنتداول فيما بيننا لنميز ما هو أصوب لنا، ونتعلم معا ما هو صالح.","34:5":"يقول أيوب: «إني بار، ولكن الله قد تنكر لحقي،","34:6":"ومع أني محق فأنا أدعى كاذبا، ومع أني بريء فإن سهمه أصابني بجرح مستعص».","34:7":"فمن هو نظير أيوب الذي يجرع الهزء كالماء،","34:8":"يواظب على معاشرة فاعلي الإثم، ويأتلف مع الأشرار،","34:9":"لأنه يقول: لا ينتفع الإنسان شيئا من إرضاء الله.","34:10":"لذلك أصغوا إلي ياذوي الفهم: حاشا لله أن يرتكب شرا أو للقدير أن يقترف خطأ،","34:11":"لأنه يجازي الإنسان بموجب أعماله، وبمقتضى طريقه يحاسبه.","34:12":"إذ حاشا لله أن يرتكب شرا، والقدير أن يعوج القضاء.","34:13":"من وكل الله بالأرض؟ ومن عهد إليه بالمسكونة؟","34:14":"إن استرجع روحه إليه واستجمع نسمته إلى نفسه","34:15":"فالبشر جميعا يفنون معا، ويعود الإنسان إلى التراب.","34:16":"فإن كنت من أولي الفهم، فاستمع إلى هذا، وأنصت لما أقول:","34:17":"أيمكن لمبغض العدل أن يحكم؟ أتدين البار القدير؟","34:18":"الذي يقول للملك: أنت عديم القيمة، وللنبلاء: أنتم أشرار؟","34:19":"الذي لا يحابي الأمراء، ولا يؤثر الأغنياء على الفقراء، لأنهم جميعا عمل يديه.","34:20":"في لحظة يموتون، تفاجئهم المنية في منتصف الليل، تتزعزع الشعوب فيفنون، ويستأصل الأعزاء من غير عون بشري،","34:21":"لأن عينيه على طرق الإنسان وهو يراقب خطواته.","34:22":"لا توجد ظلمة، ولا ظل موت، يتوارى فيهما فاعلو الإثم،","34:23":"لأنه لا يحتاج أن يفحص الإنسان مرة أخرى حتى يدعوه للمثول أمامه في محاكمة.","34:24":"يحطم الأعزاء من غير إجراء تحقيق، ويقيم آخرين مكانهم","34:25":"لذلك هو مطلع على أعمالهم، فيطيح بهم في الليل فيسحقون.","34:26":"يضربهم لشرهم على مرأى من الناس،","34:27":"لأنهم انحرفوا عن اتباعه، ولم يتأملوا في طرقه،","34:28":"فكانوا سببا في ارتفاع صراخ البائس إليه، والله يستجيب استغاثة المسكين.","34:29":"فإن هيمن بسكينته فمن يدينه، وإن وارى وجهه فمن يعاينه، سواء أكانوا شعبا أم فردا","34:30":"لكي لا يسود الفاجر، لئلا تعثر الأمة.","34:31":"هل قال أحد لله: لقد تحملت العقاب فلن أعود إلى الإساءة؟","34:32":"علمني ما لا أراه، وإن كنت قد أثمت فإنني عنه أرتدع.","34:33":"أيجزيك الله إذا بمقتضى رأيك إذا رفضت التوبة؟ لأن عليك أنت أن تختار لا أنا، فأخبرني بما تعرف.","34:34":"إن ذوي الفهم يعلنون، والحكماء الذين ينصتون إلى كلامي يقولون لي:","34:35":"إن أيوب يتكلم بجهل، وكلامه يفتقر إلى التعقل.","34:36":"ياليت أيوب يمتحن أقسى امتحان، لأنه أجاب كما يجيب أهل الشر.","34:37":"لكنه أضاف إلى خطيئته عصيانا، إذ يصفق بيننا باحتقار، مثرثرا بأقوال ضد الله!»","35:1":"وقال أليهو أيضا:","35:2":"«أتحسب هذا عدلا؟ ثم تقول: إن هذا حقي أمام الله،","35:3":"وتسأل: أية منفعة لي؟ هل أكون في حال أفضل لو لم أخطىء؟","35:4":"سأجيبك أنت وأصدقاءك معك:","35:5":"انظر إلى السماوات وتأمل: تفرس في السحب الشامخة فوقك.","35:6":"إن أثمت فماذا يؤثر هذا فيه؟ وإن كثرت خطاياك فأي شيء يلحق به؟","35:7":"وإن كنت بارا فماذا تعطيه؟ أو ماذا يأخذ من يدك؟","35:8":"إن شرك يؤثر في إنسان نظيرك، وبرك يفيد فقط أبناء الناس.","35:9":"لأن من كثرة الجور يستغيث المظلومون طلبا للخلاص من قبضة العتاة،","35:10":"ولكن لا أحد يقول: أين الله صانعي، الواهب ترنيما في الليل،","35:11":"الذي علمنا أكثر من وحوش الأرض، وجعلنا أعظم حكمة من طيور السماء.","35:12":"يستغيثون به فلا يجيب من جراء تشامخ الأشرار","35:13":"فإن كان الله لا يسمع لصراخهم الفارغ، ولا يأبه القدير له","35:14":"فكم بالأحرى لا يسمع لك عندما تقول إنك لا تراه! لكن اصبر، فدعواك أمامه","35:15":"والآن، لأنه لم يجاز في غضبه ولم يبال بمعاقبة الإثم،","35:16":"فغر أيوب فاه بالباطل، وأكثر من الكلام بجهل!»","36:1":"واستطرد أليهو:","36:2":"«تحملني قليلا فأزيدك اطلاعا، فمازال عندي ما أقوله نيابة عن الله،","36:3":"لأني أتلقى علمي من بعيد وأعزو برا لصانعي.","36:4":"حقا إن كلامي صادق، لأن الكامل في المعرفة حاضر معك.","36:5":"الله قدير ولكنه لا يحتقر الإنسان، هو قدير عظيم القدرة والفهم.","36:6":"لا يبقي على حياة الشرير إنما يقضي حق البائسين.","36:7":"لا يغض طرفه عن الصديقين، بل يقيمهم مع الملوك على العروش إلى الأبد فيتعظمون.","36:8":"وإن رسفوا في القيود، ووقعوا في حبال الشقاء،","36:9":"عندئذ يبدي لهم أفعالهم وآثامهم إذ سلكوا بغرور.","36:10":"يفتح آذانهم لتحذيراته، ويأمرهم بالتوبة عن إثمهم.","36:11":"فإن أطاعوا وعبدوه، يقضون أيامهم برغد، وسنيهم بالنعم.","36:12":"ولكن إن عصوا فبحد السيف يهلكون، ويموتون من غير فهم.","36:13":"أما فجار القلوب فيذخرون لأنفسهم غضبا، ولا يستغيثون بالله حين يعاقبهم.","36:14":"يموتون في الصبا بين مأبوني المعابد.","36:15":"أما المبتلون فينقذهم في بلائهم، وبالضيق يفتح آذانهم.","36:16":"يجتذبك من الضيق إلى رحب طليق، ويملأ مائدتك بالأطعمة الدسمة.","36:17":"ولكنك مثقل بالدينونة الواقعة على الأشرار، فالدعوى والقضاء يمسكانك.","36:18":"فاحرص لئلا يغريك الغضب بالسخرية، أو تصرفك الرشوة العظيمة عن الحق","36:19":"أيمكن لثرائك أو لجهودك الجبارة أن تدعمك فلا تغرق في الكآبة؟","36:20":"لا تتشوق إلى الليل حتى تجر الناس خارجا من بيوتهم.","36:21":"احترس أن تتحول إلى الشر، فإن هذا ما اخترته عوضا عن الشقاء.","36:22":"انظر، إن الله يتمجد في قوته. أي معلم نظيره؟","36:23":"من سن له طرقه أو قال له: لقد ارتكبت خطأ؟","36:24":"لا تنس أن تعظم عمله الذي يتغنى به الناس.","36:25":"لقد شهده الناس كلهم، وتفرسوا فيه من بعيد.","36:26":"فما أعظم الله ! ونحن لا نعرفه، وعدد سنيه لا يستقصى.","36:27":"لأنه يجتذب قطرات الماء، ويجعل سحبه تهطل أمطارا،","36:28":"تسكبها السماوات وتصبها بغزارة على الإنسان.","36:29":"أهناك من يفهم كيف تنتشر السحب، وكيف ترعد سماؤه؟","36:30":"فانظر كيف بسط بروقه حواليه وتسربل بلجج البحر.","36:31":"هكذا يطعم الله الشعوب ويزودهم بالغذاء بوفرة.","36:32":"يملأ يديه بالبروق ويأمرها أن تصيب الهدف.","36:33":"إن رعده ينذر باقتراب العاصفة، وحتى الماشية تنبيء بدنوها.","37:1":"لذلك يرتعد قلبي ويثب في موضعه.","37:2":"فأنصت، واصغ إلى زئير صوته، وإلى زمجرة فمه.","37:3":"يستل بروقه من تحت كل السماوات ويرسلها إلى جميع أقاصي الأرض،","37:4":"فتدوي زمجرة زئيره، ويرعد بصوت جلاله، وحين تتردد أصداؤه لا يكبح جماحها شيء.","37:5":"يرعد الله بصوته صانعا عجائب وآيات تفوق إدراكنا.","37:6":"يقول للثلج اهطل على الأرض، وللأمطار: انهمري بشدة.","37:7":"يوقف كل إنسان عن عمله، ليدرك كل الناس الذين خلقهم حقيقة قوته.","37:8":"فتلجأ الوحوش إلى أوجرتها، وتمكث في مآويها.","37:9":"تقبل العاصفة من الجنوب، والبرد من الشمال،","37:10":"من نسمة الله يتكون الجليد، وتتجمد بسرعة المياه الغزيرة.","37:11":"يشحن السحب المتكاثفة بالندى، ويبعثر برقه بينها.","37:12":"فتتحرك كما يشاء هو، لتنفذ كل ما يأمرها به على وجه المسكونة.","37:13":"يرسلها سواء للتأديب أو لأرضه أو رحمة منه.","37:14":"فاستمع إلى هذا ياأيوب. وتوقف وتأمل في عجائب الله.","37:15":"هل تدري كيف يتحكم الله في السحب، وكيف يجعل بروقه تومض؟","37:16":"هل تعرف كيف تتعلق السحب بتوازن؟ هذه العجائب الصادرة عن كامل المعرفة!","37:17":"أنت يامن تسخن ثيابه عندما ترين سكينة على الأرض بتأثير ريح الجنوب.","37:18":"هل يمكنك مثله أن تصفح الجلد الممتد وكأنه مرآة مسبوكة؟","37:19":"أنبئنا ماذا علينا أن نقول له، فإننا لا نحسن عرض قضيتنا بسبب الظلمة (أي الجهل)","37:20":"هل أطلب من الله أن أتكلم معه؟ أي رجل يتمنى لنفسه الهلاك؟","37:21":"لا يقدر أحد أن يحدق إلى النور عندما يكون متوهجا في السماء، بعد أن تكون الريح قد بددت عنه السحب.","37:22":"يقبل من الشمال بهاء ذهبي، إن الله مسربل بجلال مرهب.","37:23":"ولا يمكننا إدراك القدير، فهو متعظم بالقوة والعدل والبر ولا يجور،","37:24":"لذلك يرهبه الجميع، لأنه يحتقر أدعياء الحكمة».","38:1":"ثم قال الرب لأيوب من العاصفة:","38:2":"«من ذا الذي يظلم القضاء بكلام مجرد من المعرفة؟","38:3":"اشدد حقويك كرجل لأسألك فتجيبني","38:4":"أين كنت عندما أسست الأرض؟ أخبرني إن كنت ذا حكمة.","38:5":"من حدد مقاييسها، إن كنت حقا تعرف؟ أو من مد عليها خيط القياس؟","38:6":"على أي شيء استقرت قواعدها؟ ومن وضع حجر زاويتها؟","38:7":"بينما كانت كواكب السماء تترنم معا وملائكة الله تهتف بفرح.","38:8":"من حجز البحر ببوابات، عندما اندفق من رحم الأرض،","38:9":"حين جعلت السحب لباسا له والظلمة قماطه،","38:10":"عندما عينت له حدودا، وأثبت بواباته ومغاليقه في مواضعها،","38:11":"وقلت له: إلى هنا تخومك فلا تتعداها، وهنا يتوقف عتو أمواجك؟","38:12":"هل أمرت مرة الصبح في أيامك، وأريت الفجر موضعه،","38:13":"ليقبض على أكناف الأرض وينفض الأشرار منها؟","38:14":"تتشكل كطين تحت الخاتم، وتبدو معالمها كمعالم الرداء.","38:15":"يمتنع النور عن الأشرار، وتتحطم ذراعهم المرتفعة.","38:16":"هل غصت إلى ينابيع البحر، أم دلفت إلى مقاصير اللجج؟","38:17":"هل اطلعت على أبواب المنية، أم رأيت بوابات ظلال الموت؟","38:18":"هل أحطت بعرض الأرض؟ أخبرني إن كنت بكل هذا عليما.","38:19":"أين الطريق إلى مقر النور، وأين مستقر الظلمة؟","38:20":"حتى تقودها إلى تخومها وتعرف سبل مسكنها؟","38:21":"حقا أنت تعرفها لأنك آنئذ كنت قد ولدت وعشت أياما طويلة!","38:22":"هل دلفت إلى مخازن الثلج، أم رأيت خزائن البرد،","38:23":"التي ادخرتها لأوقات الضيق، ليوم المعركة والحرب؟","38:24":"ما هو السبيل إلى موضع انتشار النور، أو أين تتوزع الريح الشرقية على الأرض؟","38:25":"من حفر قنوات لسيول المطر، وممرا للصواعق،","38:26":"ليمطر على أرض مقفرة لا إنسان فيها،","38:27":"ليروي الأرض الخربة، وليستنبت الأرض عشبا؟","38:28":"هل للمطر أب؟ ومن أنجب قطرات الندى؟","38:29":"ومن أي أحشاء خرج الجمد، ومن ولد صقيع السماء؟","38:30":"تتجلد المياه كحجارة ويتجمد وجه الغمر.","38:31":"هل تربط سلاسل الثريا، أم تفك عقد الجوزاء؟","38:32":"هل تهدي كواكب المنازل في فصولها، أم تهدي النعش مع بناته؟","38:33":"هل تعرف أحكام السماوات، أم أسست سلطتها على الأرض؟","38:34":"هل ترفع صوتك آمرا الغمام فيغمرك فيض المياه؟","38:35":"هل في وسعك أن تطلق البروق فتمضي وتقول لك: ها نحن طوع أمرك؟","38:36":"من أضفى على الغيوم حكمة وأنعم على الضباب بالفهم؟","38:37":"من له الحكمة ليحصي النجوم، ومن يصب الماء من ميازيب السماء،","38:38":"حين يتلبد التراب وتتماسك كتل الطين؟","38:39":"هل تصطاد الفريسة للبؤة، أم تشبع جوع الأشبال،","38:40":"حين تتربص في العرائن وتكمن في أوجارها؟","38:41":"من يزود الغراب بصيده إذ تنعب فراخه مستغيثة بالله، وتهيم لافتقارها إلى القوت؟","39:1":"هل تدرك متى تلد أوعال الصخور أم ترقب مخاض الأيائل؟","39:2":"هل تحسب أشهر حملهن، وتعلم ميعاد وضعهن،","39:3":"حين يجثمن ليضعن صغارهن، ويتخلصن من آلام مخاضهن؟","39:4":"تكبر صغارهن، وتنمو في القفر، ثم تشرد ولا تعود.","39:5":"من أطلق سراح الفرا وفك ربط حمار الوحش؟","39:6":"لمن أعطيت الصحراء مسكنا والأرض الملحية منزلا؟","39:7":"فيسخر من جلبة المدن ولا يسمع نداء السائق؟","39:8":"يرتاد الجبال مرعى له، ويلتمس كل ما هو أخضر،","39:9":"أيرضى الثور الوحشي أن يخدمك؟ أيبيت عند معلفك؟","39:10":"أتربطه بالنير ليجر لك المحراث، أم يمهد الوادي خلفك؟","39:11":"أتتكل عليه لقوته العظيمة، وتكلفه القيام بأعمالك؟","39:12":"أتثق بعودته حاملا إليك حنطتك ليكومها في بيدرك؟","39:13":"يرفرف جناحا النعامة بغبطة، ولكن أهما جناحان مكسوان بريش المحبة؟","39:14":"فهي تترك بيضها على الأرض ليدفأ بالتراب،","39:15":"وتنسى أن القدم قد تطأ عليه، وأن بعض الحيوانات الكاسرة قد تحطمه.","39:16":"إنها تعامل صغارها بقسوة كأنها ليست لها، غير آسفة على ضياع تعبها،","39:17":"لأن الله قد أنساها الحكمة، ولم يمنحها نصيبا من الفهم.","39:18":"ولكن ما إن تبسط جناحيها، لتجري حتى تهزأ بالفرس وراكبه!","39:19":"أأنت وهبت الفرس قوته، وكسوت عنقه عرفا؟","39:20":"أأنت تجعله يثب كجرادة؟ إن نخيره الهائل لمخيف.","39:21":"يشق الوادي بحوافره، ويمرح في جم نشاطه، ويقتحم المعارك.","39:22":"يسخر من الخوف ولا يرتاع، ولا يتراجع أمام السيف.","39:23":"تصلصل عليه جعبة السهام، وأيضا بريق الرماح والحراب.","39:24":"في جريه ينهب الأرض بعنفوان وغضب ولا يستقر في مكانه عند نفخ بوق الحرب.","39:25":"عندما يدوي صوت البوق يقول: هه هه! ويستروح المعركة عن بعد، ويسمع زئير القادة وهتافهم.","39:26":"أبحكمتك يحلق الصقر ويفرد جناحيه نحو الجنوب؟","39:27":"أبأمرك يحلق النسر ويجعل وكره في العلاء؟","39:28":"يعشش بين الصخور، ويبيت فيها وعلى جرف صخري يكون معقله.","39:29":"من هناك يترصد قوته، وترقب عيناه فريسته من بعيد.","39:30":"وتلغ فراخه أيضا في الدماء، وحيث تكون الجثث تتجمع النسور».","40:1":"واستطرد الرب قائلا لأيوب:","40:2":"«أيخاصم اللائم القدير؟ليجب المشتكي على الله».","40:3":"عندئذ أجاب أيوب الرب:","40:4":"«انظر، أنا حقير فبماذا أجيبك؟ ها أنا أضع يدي على فمي","40:5":"لقد تكلمت مرة ولن أجيب، ومرتين ولن أضيف».","40:6":"حينئذ أجاب الرب أيوب من العاصفة:","40:7":"«اشدد حقويك وكن رجلا، فأسألك وتجيبني.","40:8":"أتشك في قضائي أو تستذنبني لتبرر نفسك؟","40:9":"أتملك ذراعا كذراع الله؟ أترعد بمثل صوته؟","40:10":"إذا تسربل بالجلال والعظمة، وتزين بالمجد والبهاء.","40:11":"صب فيض غضبك، وانظر إلى كل متكبر واخفضه.","40:12":"انظر إلى كل متعظم وذلله، ودس الأشرار في مواضعهم.","40:13":"اطمرهم كلهم في التراب معا، واحبس وجوههم في الهاوية.","40:14":"عندئذ أعترف لك بأن يمينك قادرة على إنقاذك.","40:15":"انظر إلى بهيموث الذي صنعته معك، فإنه يأكل العشب كالبقر.","40:16":"إن قوته في متنيه، وشدته في عضل بطنه.","40:17":"ينتصب ذيله كشجرة أرز، وعضلات فخذيه مضفورة.","40:18":"عظامه أنابيب نحاس وأطرافه قضبان حديد،","40:19":"إنه أعجب كل الخلائق، ولا يقدر أن يهزمه إلا الذي خلقه.","40:20":"تنمو الأعشاب التي يتغذى بها على الجبال، حيث تمرح وحوش البرية.","40:21":"يربض تحت شجيرات السدر، وبين الحلفاء في المستنقعات.","40:22":"يستظل بشجيرات السدر، وبالصفصاف على المياه الجارية","40:23":"لا يخامره الخوف إن هاج النهر، ويظل مطمئنا ولو اندفق نهر الأردن في فمه.","40:24":"من يقدر أن يصطاده من الأمام، أو يثقب أنفه بخزامة؟","41:1":"أيمكن أن تصطاد لوياثان بشص، أو تربط لسانه بحبل؟","41:2":"أتقدر أن تضع خزامة في أنفه، أو تثقب فكه بخطاف؟","41:3":"أيكثر من تضرعاته إليك أم يستعطفك؟","41:4":"أيبرم معك عهدا لتتخذه عبدا مؤبدا لك؟","41:5":"أتلاعبه كما تلاعب العصفور، أم تطوقه بترس ليكون لعبة لفتياتك؟","41:6":"أيساوم عليه التجار، أم يتقاسمونه بينهم؟","41:7":"أتثخن جلده بالحراب ورأسه بأسنة الرماح؟","41:8":"إن حاولت القبض عليه بيدك فإنك ستذكر ضراوة قتاله ولا تعود تقدم على ذلك ثانية!","41:9":"أي أمل في إخضاعه قد خاب، ومجرد النظر إليه يبعث على الفزع.","41:10":"لا أحد يملك جرأة كافية ليستثيره. فمن إذا، يقوى على مجابهتي؟","41:11":"من أنا مدين له فأوفيه؟ كل ما تحت جميع السماوات هو لي.","41:12":"دعني أحدثك عن أطراف لوياثان وعن قوته وتناسق قامته.","41:13":"من يخلع كساءه أو يدنو من متناول صفي أضراسه؟","41:14":"من يفتح شدقيه؟ إن دائرة أسنانه مرعبة!","41:15":"ظهره مصنوع من حراشف كتروس مصفوفة متلاصقة بإحكام، وكأنها مضغوطة بخاتم،","41:16":"متلاصقة لا ينفذ من بينها الهواء،","41:17":"متصلة بعضها ببعض، متلبدة لا تنفصل.","41:18":"عطاسه يومض نورا، وعيناه كأجفان الفجر،","41:19":"من فمه تخرج مشاعل ملتهبة، ويتطاير منه شرار نار،","41:20":"ينبعث من منخريه دخان وكأنه من قدر يغلي أو مرجل.","41:21":"يضرم نفسه الجمر، ومن فمه ينطلق اللهب.","41:22":"في عنقه تكمن قوة، وأمام عينيه يعدو الهول.","41:23":"ثنايا لحمه محكمة التماسك، مسبوكة عليه لا تتحرك.","41:24":"قلبه صلب كالصخر، صلد كالرحى السفلى.","41:25":"عندما ينهض يدب الفزع في الأقوياء، ومن جلبته يعتريهم شلل.","41:26":"لا ينال منه السيف الذي يصيبه، ولا الرمح ولا السهم ولا الحربة.","41:27":"يحسب الحديد كالقش والنحاس كالخشب النخر.","41:28":"لا يرغمه السهم على الفرار، وحجارة المقلاع لديه كالقش.","41:29":"الهراوة في عينيه كالعصافة، ويهزأ باهتزاز الرمح المصوب إليه.","41:30":"بطنه كقطع الخزف الحادة. إذا تمدد على الطين يترك آثارا مماثلة لآثار النورج.","41:31":"يجعل اللجة تغلي كالقدر، والبحر يجيش كقدر الطيب.","41:32":"يترك خلفه خطا من زبد أبيض، فيخال أن البحر قد أصابه الشيب.","41:33":"لا نظير له فوق الأرض لأنه مخلوق عديم الخوف.","41:34":"يحتقر كل ما هو متعال، وهو ملك على ذوي الكبرياء».","42:1":"فقال أيوب للرب:","42:2":"«قد أدركت أنك تستطيع كل شيء ولا يتعذر عليك أمر.","42:3":"تسألني: من ذا الذي يخفي المشورة من غير معرفة؟ حقا قد نطقت بأمور لم أفهمها، بعجائب تفوق إدراكي.","42:4":"اسمع الآن وأنا أتكلم، أسألك وأنت تعلمني.","42:5":"بسمع الأذن قد سمعت عنك والآن رأتك عيني،","42:6":"لذلك ألوم نفسي وأتوب معفرا ذاتي بالتراب والرماد».","42:7":"وبعد أن انتهى الرب من مخاطبة أيوب، قال لأليفاز التيماني: «لقد احتدم غضبي عليك وعلى كلا صديقيك، لأنكم لم تنطقوا بالصواب عني كما نطق عبدي أيوب.","42:8":"فخذوا الآن لكم سبعة ثيران وسبعة كباش، وامضوا إلى عبدي أيوب وقربوها ذبيحة محرقة عن أنفسكم، فيصلي من أجلكم، فأعفو عنكم إكراما له، لئلا أعاقبكم بمقتضى حماقتكم، لأنكم لم تنطقوا بالحق عني كعبدي أيوب».","42:9":"فذهب أليفاز التيماني وبلدد الشوحي وصوفر النعماتي وفعلوا كما أمر الرب. وأكرم الرب أيوب.","42:10":"وعندما صلى أيوب من أجل أصدقائه رده الرب من عزلة منفاه، وضاعف كل ما كان له من قبل.","42:11":"وأقبل عليه إخوته وأخواته وكل معارفه السابقين، وتناولوا معه طعاما في بيته، وأبدوا له كل رفق، وعزوه عن كل ما أنزله به الرب من بلوى، وقدم له كل واحد منهم بعض المال وخاتما من ذهب.","42:12":"وبارك الرب آخرة أيوب أكثر من أولاه، فأصبح له أربعة عشر ألف خروف وستة آلاف من الإبل وألف زوج من البقر وألف أتان.","42:13":"ورزقه الله سبعة بنين وثلاث بنات،","42:14":"فدعا الأولى يميمة، والثانية قصيعة والثالثة قرن هفوك.","42:15":"ولم توجد في كل البلاد نساء جميلات مثل بنات أيوب، ووهبهن أبوهن ميراثا بين إخوتهن.","42:16":"وعاش أيوب بعد تجربته مئة وأربعين سنة، واكتحلت عيناه برؤية أبنائه وأحفاده إلى الجيل الرابع.","42:17":"ثم مات أيوب شيخا، وقد شبع من الأيام."};
